/* Integrated Rafi 2.1 workflow. Shared shell and catalogue screens remain in index.html. */
(()=>{'use strict';
const planVersions=new Map();let renderedMonth=null;let config=null,configClub=null,cache=new Map(),loadSerial=0,card=null,saveTimer=null,recommendTimer=null,saving=null,changed=0,savedRevision=0,proposal=null,proposalError='',planContext=null,planSerial=0,cardEpoch=0,holdChanges=false;
const suspendedDrafts=new Map();
const originalRenderClubs=renderClubs;let managerSection='info';
const owner=()=>profile?.role==='OWNER',work=()=>!dev(),v3=(c=clubId)=>`/clubs/${c}/v3`,dayOf=b=>b.eventDate||b.startsAt?.slice(0,10)||'',at=b=>b.startTime?.slice(0,5)||b.startsAt?.slice(11,16)||'',until=b=>b.endTime?.slice(0,5)||b.endsAt?.slice(11,16)||'',displayDate=d=>d?niceDate(d):'Дата не выбрана',nameOf=b=>b.clientName||'Новый банкет',currentKey=()=>`${clubId}:${month.getFullYear()}-${pad(month.getMonth()+1)}`;
const sumLines=items=>items.reduce((n,l)=>n+Number(l.unitPrice||0)*Number(l.quantity||0),0);
function message(s,error=false){const node=$('v3-save');if(node){node.textContent=error?s:'';node.hidden=!error;node.className='v3-save v3-error';}}
function hours(date){const c=config?.club||{},special=JSON.parse(c.dateHours||'{}')[date],weekly=JSON.parse(c.weeklyHours||'{}');const day=date?String((new Date(date+'T12:00:00').getDay()+6)%7+1):'';return special||weekly[day]||{closed:false,open:c.opensAt||'10:00',close:c.closesAt||'21:00'};}
async function getConfig(force=false){const requested=clubId;if(!force&&configClub===requested&&config)return config;const data=await api(`${v3(requested)}/config`);if(requested===clubId){config=data;configClub=requested;halls=data.halls;}return data;}
function cachedPatch(b){for(const [key,value] of cache){if(!key.startsWith(b.clubId+':'))continue;const items=value.items.filter(x=>x.id!==b.id);if(!dayOf(b)||key===`${b.clubId}:${dayOf(b).slice(0,7)}`)items.push(b);cache.set(key,{items,time:Date.now()});}if(b.clubId===clubId){bookings=bookings.filter(x=>x.id!==b.id);if(!dayOf(b)||dayOf(b).slice(0,7)===`${month.getFullYear()}-${pad(month.getMonth()+1)}`)bookings.push(b);}}
reload=async function(){if(!await flushLayout())return;if(card&&!await flushCard())return;card=null;config=null;configClub=null;cache.clear();loadSerial++;await getConfig();applyClubTheme();await loadMonth();};
loadMonth=async function(force=false){const requested=clubId,key=currentKey(),serial=++loadSerial,year=month.getFullYear(),mo=month.getMonth()+1;const old=cache.get(key);if(old&&!force){bookings=old.items;render();if(Date.now()-old.time<20000)return;}const data=await api(`${v3(requested)}/cards?year=${year}&month=${mo}`);cache.set(key,{items:data,time:Date.now()});if(serial!==loadSerial||requested!==clubId||key!==currentKey())return;const same=JSON.stringify([...data].sort((a,b)=>a.id-b.id))===JSON.stringify([...bookings].sort((a,b)=>a.id-b.id));bookings=data;if(!card){if(page==='calendar'&&renderedMonth===key){patchCalendar(!same);}else render();}};
moveMonth=function(n){month=new Date(month.getFullYear(),month.getMonth()+n,1);selected=localDate(month);loadMonth().catch(notify);};
function bookingList(items){return items.length?items.map(b=>`<button class="v3-booking" data-v3-open="${b.id}"><div class="row"><strong>${esc(nameOf(b))}</strong><span class="v3-badge ${b.status!=='CONFIRMED'?'pending':''}">${esc(status(b))}</span></div><div style="margin-top:8px">${at(b)?esc(at(b))+' — '+esc(until(b)||'…'):'Время не выбрано'}</div><div class="v3-subtle">${b.guests?b.guests+' гостей · ':''}${config?.club.showZones!==false?esc(b.seats?.map(t=>t.tableName).join(' + ')||'Рассадка не выбрана'):''}${config?.club.showRevenue!==false?' · '+money(b.total):''}</div></button>`).join(''):'<div class="v3-empty">Банкетов пока нет</div>';}
const expired=b=>b.status==='PRELIMINARY'&&((b.holdUntil&&new Date(b.holdUntil).getTime()<=Date.now())||(dayOf(b)&&dayOf(b)<localDate(new Date())));
// Display elapsed events without changing their stored booking status.
function elapsed(b){const date=dayOf(b),today=localDate(new Date());if(!date)return false;if(date!==today)return date<today;const end=until(b);return Boolean(end&&new Date(date+'T'+end).getTime()<=Date.now());}
const displayStatus=b=>b.status==='CANCELLED'?'CANCELLED':b.status==='FINISHED'||elapsed(b)?'FINISHED':b.status;
status=b=>displayStatus(b)==='FINISHED'?'Прошёл':b.status==='CANCELLED'?'Отменено':b.status==='CONFIRMED'?'Подтверждено':expired(b)?'Срок истёк':'Предварительно';
const dotClass=b=>({CONFIRMED:'confirmed',PRELIMINARY:'pending',CANCELLED:'cancelled',FINISHED:'finished'}[displayStatus(b)]||'pending');
const calendarDots=items=>items.map(b=>`<i class="${dotClass(b)}" title="${esc(nameOf(b))} · ${esc(status(b))}"></i>`).join('');
function renderWaiting(){const node=$('v3-waiting');if(!node)return;node.hidden=config?.club.showReminders===false;const opened=node.querySelector('details')?.open||false;const pending=bookings.filter(b=>b.status==='PRELIMINARY'&&!expired(b)&&!elapsed(b)).sort((a,b)=>(dayOf(a)||'9999').localeCompare(dayOf(b)||'9999')||at(a).localeCompare(at(b))||a.id-b.id);node.innerHTML=`<details ${opened?'open':''}><summary class="v3-waiting-head"><h2>Ждут подтверждения</h2><span class="v3-waiting-count">${pending.length}</span><svg class="v3-waiting-arrow" viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></summary><div class="v3-waiting-list">${pending.length?pending.map(b=>`<button class="v3-waiting-card" data-v3-open="${b.id}"><strong>${esc(nameOf(b))}</strong><span>${esc(displayDate(dayOf(b)))}${at(b)?' · '+esc(at(b)):''}</span><small>${b.guests?b.guests+' гостей':'Гости не указаны'}</small></button>`).join(''):'<div class="v3-empty">Нет банкетов, ожидающих подтверждения</div>'}</div></details>`;}
renderCalendar=function(){renderedMonth=currentKey();const first=new Date(month.getFullYear(),month.getMonth(),1),from=new Date(first);from.setDate(1-(first.getDay()+6)%7);let grid=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(d=>`<span class="weekday">${d}</span>`).join('');for(let i=0;i<42;i++){const day=new Date(from);day.setDate(from.getDate()+i);const key=localDate(day),items=bookings.filter(b=>dayOf(b)===key);grid+=`<button class="${day.getMonth()!==month.getMonth()?'outside ':''}${key===selected?'selected ':''}${key===localDate(new Date())?'v3-today ':''}${key<localDate(new Date())?'v3-past ':''}" data-v3-day="${key}" aria-label="${displayDate(key)}; банкетов ${items.length}">${day.getDate()}<span class="v3-dots">${calendarDots(items)}</span></button>`;}
$('page').innerHTML=`<div id="tools-home-stats"></div><section class="v3-panel v3-waiting" id="v3-waiting" aria-label="Ждут подтверждения"></section><div class="v3-title v3-calendar-title"><div><h1>Бронирования</h1><div class="muted">${esc(config?.club.name||'')} · ${esc(config?.club.opensAt||'10:00')}–${esc(config?.club.closesAt||'21:00')}</div></div>${work()?'<button type="button" class="primary v3-mobile-add" data-v3-action="new" aria-label="Новый банкет" title="Новый банкет"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg></button>':''}</div><div class="v3-columns"><section class="v3-panel"><div class="row"><button class="secondary" data-v3-month="-1" aria-label="Предыдущий месяц">‹</button><h2 class="v3-month">${first.toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}</h2><button class="secondary" data-v3-month="1" aria-label="Следующий месяц">›</button></div><div class="v3-calendar">${grid}</div><div class="v3-calendar-legend" aria-label="Статусы банкетов">${[['confirmed','Подтверждённые'],['pending','Предварительные'],['cancelled','Отменённые'],['finished','Прошедшие']].map(([key,label])=>`<span><i class="${key}"></i>${label}</span>`).join('')}</div></section><section class="v3-panel" id="v3-day"></section></div>`;renderWaiting();renderDay();renderHomeStats();};
function patchCalendar(dataChanged=true){let dotsChanged=false;document.querySelectorAll('[data-v3-day]').forEach(el=>{const items=bookings.filter(b=>dayOf(b)===el.dataset.v3Day);el.setAttribute('aria-label',`${displayDate(el.dataset.v3Day)}; банкетов ${items.length}`);const dots=el.querySelector('.v3-dots');if(dots){const html=calendarDots(items);if(dots.innerHTML!==html){dots.innerHTML=html;dotsChanged=true;}}});renderWaiting();if(dataChanged||dotsChanged){renderDay();renderHomeStats();}}
function renderDay(){const node=$('v3-day');if(!node)return;const current=bookings.filter(b=>dayOf(b)===selected).sort((a,b)=>at(a).localeCompare(at(b)));node.innerHTML=`<h2>${displayDate(selected)}</h2>${bookingList(current)}`;}
const priorNavigate=navigate;
navigate=async function(to){if(!await flushLayout())return;if(card&&!card.view){clearTimeout(saveTimer);clearTimeout(recommendTimer);if(saving)await saving;suspendedDrafts.set(card.club,{card,changed,savedRevision});}card=null;cardEpoch++;bookingDirty=false;page=to;pageRenderVersion++;$('sidebar').classList.remove('open');document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.querySelectorAll('[data-mobile-page]').forEach(b=>b.classList.toggle('active',b.dataset.mobilePage===page));render();};
const priorRender=render;
render=function(){document.body.classList.toggle('v3-manager-page',dev()&&['clubs','club-info','staff','dashboard'].includes(page));if(!clubId&&dev()){renderClubs();return;}if(!clubId)return;if(card){renderCard();return;}$('globalSearchForm').style.display=!dev()&&page==='calendar'?'flex':'none';if(page==='club-info')renderClubInfo();else if(page==='staff')renderStaff().catch(notify);else if(page==='owner-stats')renderStats().catch(notify);else if(page==='presentation')renderPresentation().catch(notify);else if(page==='broadcast')renderBroadcast().catch(notify);else if(page==='map')renderMap();else priorRender();};
function draft(existing){const b=existing||{};return{...b,id:b.id||null,version:b.version,requestKey:b.requestKey||crypto.randomUUID(),clientName:b.clientName||'',phone:b.phone||'',eventDate:dayOf(b)||(!existing?selected:''),startTime:at(b),endTime:until(b)||hours(dayOf(b)||selected).close||'21:00',guests:b.guests||null,selectionKey:b.selectionKey||'',lockSelection:Boolean(b.lockSelection),menuAgreed:Boolean(b.menuAgreed),noMenu:Boolean(b.noMenu),notes:b.notes||'',prepayment:Number(b.prepayment||0),extraOrder:Number(b.extraOrder||0),items:[],status:b.status||'PRELIMINARY',seats:b.seats||[]};}
form=async function(b){if(dev())return;if(!b&&card&&!card.view){renderCard();return;}if(card&&!await flushCard())return;if(b?.id){await openDetail(b.id,true);return;}await Promise.all([getConfig(true),fetchCatalog()]);const kept=suspendedDrafts.get(clubId);if(kept){suspendedDrafts.delete(clubId);card=kept.card;card.epoch=++cardEpoch;changed=kept.changed;savedRevision=kept.savedRevision;proposal=null;proposalError='';bookingDirty=changed!==savedRevision;close();renderCard();return;}card={data:draft(),view:false,club:clubId,creationSession:crypto.randomUUID(),epoch:++cardEpoch};changed=0;savedRevision=0;proposal=null;proposalError='';bookingDirty=false;close();renderCard();};
openDetail=async function(id,edit=false){if(card&&!await flushCard())return;const c=clubId,epoch=++cardEpoch;const [data]=await Promise.all([api(`${v3(c)}/cards/${id}`),getConfig()]);if(epoch!==cardEpoch||c!==clubId)return;close();card={data:draft(data.booking),view:!edit,club:c,history:data.history,epoch};card.data.items=data.items;card.original={...card.data};changed=0;savedRevision=0;proposal=null;proposalError='';bookingDirty=false;renderCard();};
function payload(b){return{version:b.version,requestKey:b.requestKey,clientName:b.clientName,phone:b.phone,eventDate:b.eventDate||null,startTime:b.startTime||null,endTime:b.endTime||null,guests:b.guests||null,selectionKey:b.selectionKey||null,lockSelection:b.lockSelection,menuAgreed:elapsed(b)||b.status==='FINISHED'?Boolean(b.menuAgreed):b.noMenu||b.items.some(l=>l.kind==='MENU'),noMenu:Boolean(b.noMenu),notes:b.notes,prepayment:b.prepayment,extraOrder:Number(b.extraOrder||0),items:b.items.map(l=>({id:l.id||null,catalogItemId:l.catalogItemId,quantity:Number(l.quantity),clientKey:l._key||l.clientKey||(l._key=crypto.randomUUID())}))};}
function resourceChanged(){if(!card?.original||card.data.status!=='CONFIRMED')return false;return['eventDate','startTime','endTime','guests','selectionKey','lockSelection'].some(k=>card.data[k]!==card.original[k]);}
async function flushCard(apply=false){clearTimeout(saveTimer);if(!card||changed===savedRevision)return true;if(!card.data.id&&(!card.data.clientName.trim()||card.data.phone.replace(/\D/g,'').length<6)){message('Для сохранения укажите имя и телефон заказчика.',true);return false;}if(resourceChanged()&&!apply){message('Проверьте рассадку и нажмите «Применить изменения банкета»',true);return false;}if(saving){await saving;if(changed!==savedRevision)return flushCard(apply);return true;}const active=card,revision=changed,body=payload(active.data),epoch=active.epoch;message('Сохраняется…');saving=(async()=>{try{const b=await api(`${v3(active.club)}/cards${active.data.id?'/'+active.data.id:''}`,{method:active.data.id?'PUT':'POST',headers:active.creationSession?{'X-Rafi-Creation':active.creationSession}:{},body:JSON.stringify(body)});cachedPatch(b);if(card===active&&epoch===cardEpoch){active.data.id=b.id;active.data.version=b.version;active.data.status=b.status;active.data.seats=b.seats;active.data.total=b.total;active.data.balance=b.balance;for(const line of active.data.items){const fresh=b.items?.find(x=>x.clientKey===(line._key||line.clientKey));if(fresh){line.id=fresh.id;line.unitPrice=fresh.unitPrice;line.name=fresh.name;line.clientKey=fresh.clientKey;}}savedRevision=revision;if(changed===revision){active.data.selectionKey=b.selectionKey||'';active.original={...active.data};const choice=$('v3-selection');if(choice)choice.value=active.data.selectionKey;message('Сохранено');bookingDirty=false;}else message('Сохраняются следующие изменения…');}return true;}catch(e){if(card===active)message(e.message+' Изменения не сохранены.',true);return false;}finally{saving=null;}})();const ok=await saving;if(ok&&card===active&&changed!==savedRevision&&!resourceChanged())return flushCard(apply);return ok;}
function changeCard(){changed++;bookingDirty=true;message('Сохраняется…');clearTimeout(saveTimer);saveTimer=setTimeout(()=>flushCard(),650);updateCardSummary();clearTimeout(recommendTimer);recommendTimer=setTimeout(recommend,250);}
let seatingMonthKey=null,seatingMonthChecked=0,seatingBookings=[];
async function recommend(){if(!card||card.view||elapsed(card.data)||card.data.status==='FINISHED')return;const waitingCard=card,waitingDate=card.data.eventDate;if(waitingDate&&(seatingMonthKey!==card.club+':'+waitingDate.slice(0,7)||Date.now()-seatingMonthChecked>15000)){try{const d=new Date(waitingDate+'T12:00:00'),data=await api(`${v3(card.club)}/cards?year=${d.getFullYear()}&month=${d.getMonth()+1}`);if(card!==waitingCard||card.data.eventDate!==waitingDate)return;seatingBookings=data;seatingMonthKey=card.club+':'+waitingDate.slice(0,7);seatingMonthChecked=Date.now();}catch(e){if(card===waitingCard){proposalError='Не удалось проверить свободные столы. '+e.message;updateCardSummary();}return;}}autoSelectTable();const active=card,revision=changed,epoch=card.epoch,requestId=card.data.id;try{const p=await api(`${v3(active.club)}/recommend${active.data.id?'?exclude='+active.data.id:''}`,{method:'POST',body:JSON.stringify(payload(active.data))});if(card!==active||revision!==changed||epoch!==cardEpoch)return;if(active.data.id!==requestId){recommend();return;}proposal=p;proposalError='';}catch(e){if(card!==active||revision!==changed)return;proposal=null;proposalError=e.message;}updateCardSummary();drawPlan();}
function field(key,label,type='text',attrs=''){const b=card.data;return`<label>${label}<input data-v3-field="${key}" type="${type}" value="${esc(b[key]??'')}" ${attrs}></label>`;}
function lineView(kind){return card.data.items.filter(l=>l.kind===kind).map(l=>`<div class="v3-line"><span>${esc(l.name)}${kind==='SERVICE'&&Number(l.quantity)===1?'':' × '+l.quantity}</span><strong>${money(Number(l.unitPrice)*l.quantity)}</strong></div>`).join('')||(kind==='MENU'&&card.data.noMenu?'Без меню':'Не заказаны');}
function editLines(kind){return lineView(kind);}
function orderSection(kind,view=false){const b=card.data,lines=b.items.filter(l=>l.kind===kind),count=lines.reduce((n,l)=>n+Number(l.quantity),0);return`<section class="v3-order-section ${view?'tools-order-view':'tools-order-edit'}"><div class="v3-order-heading"><h2>${kind==='MENU'?'Меню':'Услуги'}</h2>${!view?`<button type="button" class="v3-round-plus" data-v3-picker="${kind}" aria-label="${kind==='MENU'?'Выбрать меню':'Выбрать услуги'}">＋</button>`:''}${!view?`<button type="button" class="v3-order-toggle" data-v3-order-toggle="${kind}" aria-label="Раскрыть ${kind==='MENU'?'меню':'услуги'}" aria-expanded="false" aria-controls="v3-order-details-${kind}" ${lines.length?'':'hidden'}><span aria-hidden="true"></span></button>`:''}</div><details id="v3-order-details-${kind}" class="v3-section v3-order-details"><summary><span id="v3-order-summary-${kind}">${lines.length?lines.length+' поз. · '+(kind==='MENU'?count+' шт. · ':'')+money(sumLines(lines)):''}</span></summary><div id="v3-lines-${kind}">${lineView(kind)}</div></details></section>`;}
function refreshOrder(){for(const kind of ['MENU','SERVICE']){const toggle=document.querySelector(`[data-v3-order-toggle="${kind}"]`);if(toggle)toggle.hidden=!card.data.items.some(l=>l.kind===kind);const lines=card.data.items.filter(l=>l.kind===kind),node=$('v3-lines-'+kind),summary=$('v3-order-summary-'+kind);if(node)node.innerHTML=lineView(kind);if(summary)summary.textContent=lines.length?lines.length+' поз. · '+(kind==='MENU'?lines.reduce((n,l)=>n+Number(l.quantity),0)+' шт. · ':'')+money(sumLines(lines)):'';}}
function showPicker(kind){
 if(!card||card.view)return;
 const active=card,staged=card.data.items.map(l=>({...l})),catalog=kind==='MENU'?menu:services,dialog=document.createElement('dialog'),before=document.activeElement;
 dialog.className='v3-catalog-dialog';dialog.setAttribute('aria-label',kind==='MENU'?'Выбор меню':'Выбор услуг');
 const quantity=id=>staged.filter(l=>l.kind===kind&&l.catalogItemId===id).reduce((n,l)=>n+Number(l.quantity),0);
 const groups=[...new Set(catalog.map(i=>i.category||'Без категории'))];
 const counted=item=>kind==='MENU';
 dialog.innerHTML=`<div class="v3-picker-head"><h2>${kind==='MENU'?'Меню':'Услуги'}</h2><button type="button" class="v3-picker-close" aria-label="Закрыть">×</button></div><div class="v3-picker-list">${groups.map((category,index)=>`<details class="v3-picker-category" data-category-index="${index}"><summary><span>${esc(category)}</span><span class="v3-category-count"></span><span class="v3-chevron" aria-hidden="true"></span></summary>${catalog.filter(i=>(i.category||'Без категории')===category).map(item=>`<div class="v3-picker-item"><div><strong>${esc(item.name)}</strong><span>${money(item.price)}${counted(item)?' / '+esc(item.unit||'шт.'):''}</span></div>${counted(item)?`<div class="v3-stepper"><button type="button" data-pick-id="${item.id}" data-delta="-1" aria-label="Уменьшить ${esc(item.name)}">−</button><output data-count="${item.id}">${quantity(item.id)}</output><button type="button" data-pick-id="${item.id}" data-delta="1" aria-label="Добавить ${esc(item.name)}">＋</button></div>`:`<label class="v3-service-choice"><input type="checkbox" data-service-pick="${item.id}" ${quantity(item.id)?'checked':''} aria-label="${esc(item.name)}"><span aria-hidden="true"></span></label>`}</div>`).join('')}</details>`).join('')||'<div class="v3-empty">В каталоге пока нет позиций</div>'}</div><div class="v3-picker-foot"><span id="v3-picker-total" aria-live="polite"></span><button type="button" class="primary" data-pick-apply>Готово</button></div>`;
 dialog.addEventListener('toggle',e=>{if(e.target.matches('.v3-picker-category')&&e.target.open)for(const group of dialog.querySelectorAll('.v3-picker-category'))if(group!==e.target)group.open=false;},true);
 const total=()=>{dialog.querySelector('#v3-picker-total').textContent=money(sumLines(staged.filter(l=>l.kind===kind)));for(const button of dialog.querySelectorAll('[data-delta="-1"]'))button.disabled=quantity(Number(button.dataset.pickId))===0;for(const group of dialog.querySelectorAll('[data-category-index]')){const category=groups[Number(group.dataset.categoryIndex)],selected=catalog.filter(i=>(i.category||'Без категории')===category&&quantity(i.id)>0).length;group.querySelector('.v3-category-count').textContent=selected?selected+' выбрано':'';}};
 const add=item=>staged.push({catalogItemId:item.id,name:item.name,kind,unitPrice:item.price,quantity:1,unit:item.unit,_key:crypto.randomUUID()});
 dialog.addEventListener('change',e=>{if(!e.target.dataset.servicePick)return;const id=Number(e.target.dataset.servicePick),item=catalog.find(i=>i.id===id);if(e.target.checked){if(!quantity(id))add(item);}else{for(let i=staged.length-1;i>=0;i--)if(staged[i].catalogItemId===id&&staged[i].kind===kind)staged.splice(i,1);}total();});
 dialog.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.classList.contains('v3-picker-close')){dialog.close();return;}if(button.hasAttribute('data-pick-apply')){if(card===active){card.data.items=staged;if(kind==='MENU')card.data.noMenu=false;card.data.menuAgreed=card.data.noMenu||staged.some(l=>l.kind==='MENU');refreshOrder();changeCard();}dialog.close();return;}if(button.dataset.pickId){const id=Number(button.dataset.pickId),delta=Number(button.dataset.delta),item=catalog.find(l=>l.id===id);let line=delta>0?staged.find(l=>l.catalogItemId===id&&l.kind===kind):staged.findLast(l=>l.catalogItemId===id&&l.kind===kind);if(delta>0&&quantity(id)>=10000)return;if(delta>0){if(line)line.quantity=Number(line.quantity)+1;else add(item);}else if(line){line.quantity--;if(line.quantity===0)staged.splice(staged.indexOf(line),1);}dialog.querySelector(`[data-count="${id}"]`).textContent=quantity(id);total();}});
 dialog.addEventListener('close',()=>{dialog.remove();if(document.activeElement===document.body)before?.focus({preventScroll:true});},{once:true});document.body.append(dialog);total();dialog.showModal();
}

async function fetchCatalog(){const c=clubId;const result=await Promise.all([api(apiClub('/catalog?kind=MENU')),api(apiClub('/catalog?kind=SERVICE'))]);if(c!==clubId)return;[menu,services]=result;}
function cardActions(){if(dev())return '';const b=card.data,locked=b.status==='CANCELLED',past=elapsed(b)||b.status==='FINISHED';return`<div class="v3-card-actions"><section class="v3-action-group"><h3>Управление банкетом</h3><div class="v3-actions">${!dev()&&!locked?(card.view?'<button class="secondary" data-v3-action="edit">Редактировать</button>':past?'<button class="primary" data-v3-action="apply">Сохранить исправления</button>':b.status==='CONFIRMED'?'<button class="primary" data-v3-action="apply">Применить изменения банкета</button>':'<button class="primary" data-v3-action="save-draft">Сохранить заявку</button><button class="secondary" data-v3-action="confirm">Подтвердить банкет</button>'):''}${!dev()&&b.id&&b.status!=='FINISHED'&&!elapsed(b)?(b.status==='CANCELLED'?'<button class="secondary" data-v3-action="restore">Восстановить</button>':'<button class="secondary v3-danger-action" data-v3-action="cancel">Отменить банкет</button>'):''}${!dev()&&b.id&&b.status==='PRELIMINARY'&&!past?'<button class="secondary v3-danger-action" data-v3-action="delete">Удалить</button>':''}${!dev()&&b.id&&b.status==='PRELIMINARY'&&!past&&b.holdUntil?'<button class="secondary" data-v3-action="extend">Продлить на 24 часа</button>':''}${!card.view&&!dev()?'<button class="secondary" data-v3-action="discard">Отменить изменения</button>':''}</div></section>${b.id?'<section class="v3-action-group v3-documents"><h3>Документы</h3><div class="v3-actions"><button class="secondary" data-v3-action="pdf">Карточка PDF</button><button class="secondary" data-v3-action="kitchen">Для кухни</button></div></section>':''}</div>`;}
function historyText(value){return String(value??'0').replace(/\bnull\b/g,'0').replace(/\b(\d{4})-(\d{2})-(\d{2})\b/g,'$3.$2.$1').replace(/\b(?:CREATE|UPDATE|CANCELLED|CONFIRMED|PRELIMINARY|FINISHED|RESTORE|EXTEND|DELETE|STATUS|ADMIN|OWNER|DEVELOPER|developer|admin|owner)\b/g,key=>({CREATE:'Создание',UPDATE:'Изменение',CANCELLED:'Отменён',CONFIRMED:'Подтверждён',PRELIMINARY:'Предварительный',FINISHED:'Завершён',RESTORE:'Восстановление',EXTEND:'Продление',DELETE:'Удаление',STATUS:'Статус',ADMIN:'Администратор',OWNER:'Управляющий',DEVELOPER:'Разработчик',developer:'Разработчик',admin:'Администратор',owner:'Управляющий'}[key]||key));}
function historyChanges(event){
 const detail=String(event.detail||'');
 try{const data=JSON.parse(detail);if(data.format==='rafi-changes-v1'&&Array.isArray(data.changes))return{rows:data.changes.map(change=>({field:String(change.field||'Изменение'),before:String(change.before??'0'),after:String(change.after??'0')})),omitted:Number(data.omitted)||0};}catch(ignore){}
 const parts=detail.split(/\s+→\s+/);
 const parse=text=>{const fields={};for(const part of text.split(/,\s*(?=[^,:]+:)/)){const at=part.indexOf(':');if(at>0)fields[part.slice(0,at).trim().toLocaleLowerCase('ru-RU')]=part.slice(at+1).trim();}return fields;};
 if(parts.length===2){const before=parse(parts[0]),after=parse(parts[1]),names={'дата':'Дата банкета','время':'Время банкета','гостей':'Гостей','предоплата':'Предоплата','дозаказ':'Дозаказ'};const rows=Object.keys(after).filter(key=>after[key]!==before[key]).map(key=>({field:names[key]||key,before:historyText(before[key]??'0'),after:historyText(after[key])}));if(rows.length)return{rows,omitted:0};if(Object.keys(after).length)return{rows:[],omitted:0};}
 return{rows:[],text:detail?historyText(detail):'',omitted:0};
}
function renderHistory(){
 const events=card.history||[];if(!events.length)return'<div class="v3-empty">История появится после сохранения</div>';
 const groups=new Map();for(const event of [...events].sort((a,b)=>String(b.occurredAt||'').localeCompare(String(a.occurredAt||''))||Number(b.id||0)-Number(a.id||0))){const date=String(event.occurredAt||'').slice(0,10);if(!groups.has(date))groups.set(date,[]);groups.get(date).push(event);}
 const labels={CREATE:'Банкет создан',UPDATE:'Карточка изменена',CANCELLED:'Банкет отменён',CONFIRMED:'Бронь подтверждена',RESTORE:'Бронь восстановлена',EXTEND:'Ожидание продлено на 24 часа',FINISHED:'Банкет завершён',DELETE:'Банкет удалён'};
 return [...groups].map(([date,items])=>`<section class="v3-history-day"><h3>${date?esc(displayDate(date)):'Дата не указана'}</h3>${items.map(event=>{const changes=historyChanges(event),time=String(event.occurredAt||'').slice(11,16),creating=event.action==='CREATE';return`<article class="v3-history-event"><div class="v3-history-meta"><time>${esc(time||'—')}</time><span>${esc(historyText(event.actor))}</span></div><h4>${esc(labels[event.action]||historyText(event.action))}</h4>${changes.rows.length?`<dl class="v3-history-changes">${changes.rows.map(change=>`<div><dt>${esc(change.field)}</dt><dd>${!creating?`<span class="v3-history-before">${esc(historyText(change.before)||'Не указано')}</span><span class="v3-history-arrow" aria-label="изменено на">→</span>`:''}<span class="v3-history-after">${esc(historyText(change.after)||'Не указано')}</span></dd></div>`).join('')}</dl>`:changes.text?`<p class="v3-history-legacy">${esc(changes.text)}</p>`:'<p class="v3-history-legacy">Данные карточки сохранены</p>'}${changes.omitted?`<p class="v3-history-legacy">Ещё изменений: ${changes.omitted}</p>`:''}</article>`;}).join('')}</section>`).join('');
}

function cardHeading(){const b=card.data;return`<div class="v3-card-heading"><div><span class="muted">Заказчик банкета</span><h1 id="v3-card-title">${esc(nameOf(b))}</h1></div><span class="v3-status-chip ${dotClass(b)}">${esc(status(b))}</span></div>`;}
function renderCard(){const b=card.data,view=card.view||dev()||b.status==='CANCELLED';if(view)card.view=true;card.original=card.original||{...b};$('page').innerHTML=`<div class="v3-savebar"><button class="secondary" data-v3-action="back">‹ К банкетам</button><span id="v3-save" class="v3-save v3-error" hidden role="alert"></span></div><div class="v3-banquet-card">${view?viewCard():elapsed(b)||b.status==='FINISHED'?editPastCard():editCard()}${cardActions()}</div>${dev()?'':`<details class="v3-section"><summary>История изменений</summary><div class="v3-history">${renderHistory()}</div></details>`}`;drawPlan();if(!view){updateCardSummary();recommend();} }
function paymentCard(view=false){const b=card.data,total=sumLines(b.items)+Number(b.extraOrder||0);return`<section class="v3-panel v3-payment-card"><h2>Оплата</h2><div class="v3-price-row"><span>Меню</span><strong id="v3-menu-price">${money(sumLines(b.items.filter(l=>l.kind==='MENU')))}</strong></div><div class="v3-price-row"><span>Услуги</span><strong id="v3-service-price">${money(sumLines(b.items.filter(l=>l.kind==='SERVICE')))}</strong></div>${view?`<div class="v3-price-row"><span>Дозаказ</span><strong>${money(b.extraOrder||0)}</strong></div>`:`<div class="v3-fields v3-payment-fields">${field('extraOrder','Дозаказ, ₽','number','min="0" step="0.01"')}${field('prepayment','Предоплата, ₽','number','min="0" step="0.01"')}</div>`}<div class="v3-price-row v3-total-price"><span>Итого</span><strong id="v3-total-price">${money(total)}</strong></div>${view?`<div class="v3-price-row"><span>Предоплата</span><strong>${money(b.prepayment)}</strong></div>`:''}<div class="v3-price-row v3-balance-price"><span>Осталось оплатить</span><strong id="v3-balance-price">${money(Math.max(0,total-b.prepayment))}</strong></div><div class="v3-subtle" id="v3-money" hidden></div><div class="v3-subtle" id="v3-overpayment">${b.prepayment>total?'Переплата '+money(b.prepayment-total):''}</div></section>`;}
function seatingCard(){const b=card.data;return`<section class="v3-seating-card v3-visual-seating"><h2>Рассадка</h2><input type="hidden" id="v3-selection" data-v3-field="selectionKey" value="${esc(b.selectionKey)}"><p class="v3-subtle">Выберите свободный стол на схеме. Дополнительные столы подберём по количеству гостей.</p><div id="v3-plan-root"></div><div class="v3-notice" id="v3-recommend" role="status"></div><details class="v3-section v3-seating-options"><summary>Настройки рассадки</summary><label class="v3-check"><input type="checkbox" data-v3-field="lockSelection" ${b.lockSelection?'checked':''}>Не заменять выбранную зону</label><p class="v3-subtle v3-lock-help">Даже для небольшой компании оставим эту зону. При нехватке мест добавим свободные столы.</p></details></section>`;}

function viewCard(){const b=card.data;return`<div class="v3-columns v3-banquet-columns"><section class="v3-panel v3-main-card">${cardHeading()}<div class="v3-summary v3-card-facts"><div><span class="muted">Телефон</span><strong>${esc(b.phone||'Не указан')}</strong></div><div><span class="muted">Дата</span><strong>${displayDate(b.eventDate)}</strong></div><div><span class="muted">Время</span><strong>${b.startTime?esc(b.startTime)+' — '+esc(b.endTime||'…'):'Не выбрано'}</strong></div><div><span class="muted">Гостей</span><strong>${b.guests||'—'}</strong></div></div><section class="v3-seating-card"><h2>Место банкета</h2><div class="tools-booking-place"><div id="v3-plan-root" class="tools-readonly-plan"></div><div class="tools-table-names">${b.seats.map(s=>`<span><strong>${esc(s.tableName)}</strong><small>${s.guests||0} гостей</small></span>`).join('')||'<span>Рассадка не выбрана</span>'}</div></div></section>${orderSection('MENU',true)}${orderSection('SERVICE',true)}${b.notes?`<details class="v3-section"><summary>Комментарий</summary><p class="v3-notes">${esc(b.notes)}</p></details>`:''}</section>${paymentCard(true)}</div>`;}
function editPastCard(){const b=card.data;return`<div class="v3-notice">Банкет прошёл. Можно исправить комментарий, предоплату и дозаказ.</div><div class="v3-columns v3-banquet-columns"><section class="v3-panel">${cardHeading()}<p>${displayDate(b.eventDate)} · ${esc(b.startTime||'')}–${esc(b.endTime||'')}</p>${orderSection('MENU',true)}${orderSection('SERVICE',true)}<label>Комментарий<textarea data-v3-field="notes" maxlength="255">${esc(b.notes||'')}</textarea></label></section>${paymentCard()}</div>`;}
function editCard(){const b=card.data;return`<div class="v3-notice" id="v3-hints" aria-live="polite"></div><div class="v3-columns v3-banquet-columns"><section class="v3-panel v3-main-card">${cardHeading()}<div class="v3-fields v3-card-fields">${field('clientName','Имя заказчика','text','autocomplete="name"')}${field('phone','Телефон','tel','autocomplete="tel"')}${field('eventDate','Дата','date')}${field('guests','Гостей','number','min="1" max="2000" step="1"')}${field('startTime','Начало','text','placeholder="14:00" inputmode="numeric" list="v3-times"')}${field('endTime','Окончание','text','placeholder="21:00" inputmode="numeric" list="v3-times"')}</div><datalist id="v3-times">${Array.from({length:48},(_,i)=>`<option value="${pad(Math.floor(i/2))}:${i%2?'30':'00'}">`).join('')}</datalist><button class="secondary v3-closing" data-v3-action="closing">До закрытия</button>${seatingCard()}${orderSection('MENU')}<label class="v3-check v3-no-menu"><input type="checkbox" data-v3-field="noMenu" ${b.noMenu?'checked':''} ${b.items.some(l=>l.kind==='MENU')?'disabled':''}>Меню не требуется</label>${orderSection('SERVICE')}<details class="v3-section"><summary>Комментарий</summary><div class="v3-fields"><label class="v3-full">Примечание<textarea data-v3-field="notes" maxlength="255">${esc(b.notes)}</textarea></label></div></details></section>${paymentCard()}</div>`;}

function updateCardSummary(){if(!card||card.view)return;const b=card.data,missing=[];const title=$('v3-card-title');if(title)title.textContent=nameOf(b);if(!b.clientName.trim())missing.push('имя');if(b.phone.replace(/\D/g,'').length<6)missing.push('телефон');if(!b.eventDate)missing.push('дата');if(!b.startTime)missing.push('начало');if(!b.endTime)missing.push('окончание');if(!b.guests)missing.push('гости');if(!b.selectionKey)missing.push('рассадка');if(!b.noMenu&&!b.items.some(l=>l.kind==='MENU'))missing.push('меню');const h=$('v3-hints');if(h)h.textContent=missing.length?'Осталось заполнить: '+missing.join(', '):'Важные разделы заполнены. Можно подтвердить банкет.';const total=sumLines(b.items)+Number(b.extraOrder||0),m=$('v3-money');if(m)m.textContent='Итого '+money(total)+' · остаток '+money(Math.max(0,total-b.prepayment))+(b.prepayment>total?' · переплата '+money(b.prepayment-total):'');for(const [id,value] of [['v3-menu-price',sumLines(b.items.filter(l=>l.kind==='MENU'))],['v3-service-price',sumLines(b.items.filter(l=>l.kind==='SERVICE'))],['v3-total-price',total],['v3-balance-price',Math.max(0,total-b.prepayment)]]){const node=$(id);if(node)node.textContent=money(value);}const over=$('v3-overpayment');if(over)over.textContent=b.prepayment>total?'Переплата '+money(b.prepayment-total):'';const r=$('v3-recommend');if(r){r.textContent=proposalError||(proposal?.tables?.length?'Рекомендуем: '+proposal.tables.map(t=>t.name+' · '+t.guests+' чел.').join(' + ')+(proposal.warning?' · '+proposal.warning:''):(!b.eventDate||!b.startTime||!b.endTime?'Укажите дату и время для проверки свободных столов':!b.guests?'Укажите количество гостей':'Выберите свободный стол на схеме'));r.classList.toggle('v3-error',Boolean(proposalError));if(!proposal?.tables?.length&&b.selectionKey?.startsWith('t:')){const table=config.tables.find(t=>String(t.id)===b.selectionKey.slice(2));if(table)r.textContent+=' · '+table.name+' · до '+tableCapacity(table)+' мест';}}}
function chairMarks(t,type,n){
 const cap=Math.max(1,tableCapacity(t)),count=Math.min(cap,Math.max(0,Number(n)||0)),vertical=t.height/layoutRatio()>t.width;
 const physicalWidth=Math.max(1,t.width),physicalHeight=Math.max(1,t.height/layoutRatio()),long=vertical?physicalHeight:physicalWidth;
 const side=Math.max(1,Math.ceil((cap-2)/2)),size=Math.max(.65,Math.min(2,long/(side+1)*.72,Math.min(physicalWidth,physicalHeight)*.6)),positions=[];
 const dx=size*.73/physicalWidth,dy=size*.73/physicalHeight;
 if(type?.shape==='ROUND'){
  for(let i=0;i<cap;i++){const a=-Math.PI/2+i*2*Math.PI/cap;positions.push([.5+Math.cos(a)*(.5+dx),.5+Math.sin(a)*(.5+dy),a*180/Math.PI+90]);}
 }else if(type?.shape==='SQUARE'){
  const perSide=[0,0,0,0];for(let i=0;i<cap;i++)perSide[i%4]++;
  perSide.forEach((amount,sideIndex)=>{for(let i=0;i<amount;i++){const f=(i+1)/(amount+1);positions.push(sideIndex===0?[f,-dy,0]:sideIndex===1?[1+dx,f,90]:sideIndex===2?[1-f,1+dy,180]:[-dx,1-f,270]);}});
 }else{
  const top=Math.ceil(Math.max(0,cap-2)/2),bottom=Math.floor(Math.max(0,cap-2)/2);
  for(let i=0;i<Math.max(top,bottom);i++){if(i<top){const f=(i+1)/(top+1);positions.push(vertical?[-dx,f,270]:[f,-dy,0]);}if(i<bottom){const f=(i+1)/(bottom+1);positions.push(vertical?[1+dx,f,90]:[f,1+dy,180]);}}
  if(positions.length<cap)positions.push(vertical?[.5,-dy,0]:[-dx,.5,270]);if(positions.length<cap)positions.push(vertical?[.5,1+dy,180]:[1+dx,.5,90]);
 }
 return positions.slice(0,count).map(([x,y,angle])=>`<span class="v3-chair" aria-hidden="true" style="left:${x*100}%;top:${y*100}%;--chair-size:${size}cqw;--chair-angle:${angle}deg"></span>`).join('');
}

let seatingView='plan',mapTime='14:00',mapEnd='21:00';
function seatingState(){const context=card?.data||planContext,checked=Boolean(context?.eventDate&&context?.startTime&&context?.endTime&&context.startTime<context.endTime),busy=new Map(),groups=[];if(checked)for(const b of (card&&!card.view?seatingBookings:bookings)){if(b.id===card?.data.id||b.status==='CANCELLED'||b.status==='PRELIMINARY'&&(!b.holdUntil||new Date(b.holdUntil)<=new Date())||dayOf(b)!==context.eventDate||at(b)>=context.endTime||until(b)<=context.startTime)continue;const actual=(b.seats||[]).filter(s=>config.tables.some(t=>t.id===s.tableId&&!t.archived));if(!actual.length)continue;const color=['#4f80ad','#9a6eae','#bd8051','#568a80','#b26f8b'][Math.abs(Number(b.id)||0)%5];groups.push({booking:b,color,tables:actual});for(const seat of actual)busy.set(seat.tableId,{booking:b,color,guests:seat.guests});}return{checked,busy,groups,chosen:new Map((card?.view?card.data.seats.map(t=>({id:t.tableId,guests:t.guests})):proposal?.tables||[]).map(t=>[t.id,t.guests]))};}
function seatingLegend(){return'<div class="sc-legend"><span><i class="sc-free-dot"></i>Свободен</span><span><i class="sc-busy-dot"></i>Занят</span><span><i class="sc-chosen-dot"></i>Выбран для банкета</span></div>';}
function groupLabels(state){return state.groups.map(g=>`<button type="button" class="sc-group" style="--zone-color:${g.color}" data-v3-open="${g.booking.id}"><i></i><span>Зона банкета · ${esc(nameOf(g.booking))}</span><small>${g.tables.length} стол. · ${at(g.booking)}–${until(g.booking)}</small></button>`).join('');}
function miniTable(t,n){const type=config.types.find(a=>a.id===t.typeId),shape=type?.shape||'RECTANGLE',cap=tableCapacity(t),points=[];if(shape==='ROUND'){for(let i=0;i<cap;i++){const a=-Math.PI/2+i*Math.PI*2/cap;points.push([50+Math.cos(a)*30,50+Math.sin(a)*42,a*180/Math.PI+90]);}}else if(shape==='SQUARE'){for(let side=0;side<4;side++){const count=Math.floor(cap/4)+(side<cap%4?1:0);for(let i=0;i<count;i++){const f=28+(i+1)/(count+1)*44;points.push(side===0?[f,20,0]:side===1?[76,f,90]:side===2?[100-f,80,180]:[24,100-f,270]);}}}else{const top=Math.ceil((cap-2)/2),bottom=Math.floor((cap-2)/2);for(let i=0;i<Math.max(top,bottom);i++){if(i<top)points.push([20+(i+.5)/top*60,23,0]);if(i<bottom)points.push([20+(i+.5)/bottom*60,77,180]);}if(points.length<cap)points.push([11,50,270]);if(points.length<cap)points.push([89,50,90]);}return`<span class="sc-mini ${shape.toLowerCase()}" aria-hidden="true">${points.slice(0,Math.min(n,cap)).map(([x,y,a])=>`<span class="sc-chair" style="left:${x}%;top:${y}%;--a:${a}deg"></span>`).join('')}<span class="sc-top"></span></span>`;}
function renderSeatCards(target='sc-tables'){const root=$(target);if(!root||!config)return;if(target==='v3-seat-cards'){root.hidden=!card?.data.guests;if(root.hidden)return;}const state=seatingState(),rank=t=>state.chosen.has(t.id)?0:state.busy.has(t.id)?2:1;root.innerHTML=config.tables.filter(t=>!t.archived).sort((a,b)=>rank(a)-rank(b)||a.id-b.id).map(t=>{const selected=state.chosen.has(t.id),used=state.busy.get(t.id),n=selected?state.chosen.get(t.id):used?(used.guests??tableCapacity(t)):tableCapacity(t),label=selected?'Выбран':used?'Занят':state.checked?'Свободен':'Время не указано',hall=config.halls.find(h=>h.id===t.hallId);return`<article class="sc-table ${selected?'sc-chosen':used?'sc-busy':state.checked?'sc-free':'sc-unknown'}"><button type="button" class="sc-select-table" data-v3-table="${t.id}" aria-label="${esc(t.name)}, ${tableCapacity(t)} мест, ${label}" ${card&&used?'disabled':''}><span class="sc-table-head"><span>${hall?esc(hall.name):'Отдельный стол'}</span><span>${label}</span></span>${miniTable(t,n)}<strong>${esc(t.name)}</strong><span class="sc-table-capacity">${selected?n+' гостей · максимум '+tableCapacity(t):'До '+tableCapacity(t)+' гостей'}</span>${used?`<span class="sc-table-booking" style="--zone-color:${used.color}"><i></i>${esc(nameOf(used.booking))}<small>${at(used.booking)}–${until(used.booking)}</small></span>`:''}</button>${!card&&!dev()&&!used?`<button type="button" class="sc-create" data-seat-new="${t.id}" aria-label="Создать банкет: ${esc(t.name)}">${layoutIcon('plus')}Новый банкет</button>`:''}</article>`;}).join('')||'<div class="v3-empty">Столы ещё не добавлены</div>';}
function drawPlan(){const target=$('v3-plan-root');if(!target||!config)return;const state=seatingState();if(!target.querySelector('.v3-plan'))target.innerHTML='<div class="sc-groups"></div><div class="v3-plan"><div class="v3-table-layer"></div></div>'+seatingLegend();const stage=target.querySelector('.v3-plan');applySavedPlanView(stage);stage.style.backgroundImage=`url('/api/clubs/${clubId}/plan-image?v=${planVersions.get(clubId)||1}')`;target.querySelector('.sc-groups').innerHTML=groupLabels(state);
 stage.querySelector('.v3-table-layer').innerHTML=config.tables.filter(t=>!t.archived).map(t=>{const type=config.types.find(x=>x.id===t.typeId),chosen=state.chosen.has(t.id),used=state.busy.get(t.id),n=chosen?state.chosen.get(t.id):used?(used.guests??tableCapacity(t)):tableCapacity(t);return`<button type="button" class="v3-table ${type?.shape==='ROUND'?'round ':type?.shape==='SQUARE'?'square ':''}${chosen?'chosen ':used?'busy ':state.checked?'free ':'unknown '}" data-v3-table="${t.id}" ${card&&used?'disabled':''} aria-label="${esc(t.name)}, ${tableCapacity(t)} мест, ${chosen?'выбран':used?'занят':state.checked?'свободен':'укажите время'}" style="left:${t.x}%;top:${t.y}%;width:${t.width}%;height:${t.height}%;transform:rotate(${Number(t.rotation)||0}deg);${used?'--zone-color:'+used.color:''}">${chairMarks(t,type,n)}<span class="wood"><span style="transform:rotate(${-(Number(t.rotation)||0)}deg)">${esc(t.name)}${used?'<i class="sc-group-dot"></i>':''}</span></span></button>`;}).join('');renderSeatCards('v3-seat-cards');}
function applySavedPlanView(stage){let viewport=stage.parentElement;if(!viewport.classList.contains('v3-plan-viewport')){viewport=document.createElement('div');viewport.className='v3-plan-viewport';stage.before(viewport);viewport.append(stage);}const c=config.club,z=Math.max(1,Math.min(4,Number(c.planZoom)||1));viewport.style.aspectRatio=String(layoutRatio());stage.style.aspectRatio=String(layoutRatio());stage.style.width=z*100+'%';stage.style.left=(50-(Number(c.planCenterX)||50)*z)+'%';stage.style.top=(50-(Number(c.planCenterY)||50)*z)+'%';}
function setMapContext(){planContext={eventDate:selected,startTime:mapTime,endTime:mapEnd};}
renderMap=function(){setMapContext();proposal=null;$('page').innerHTML=`<div class="sc-page-head"><h1>Столы и зоны</h1></div><div class="sc-date-time"><label>Дата<input type="date" id="v3-map-date" value="${selected}" aria-label="Дата рассадки"></label><label>С<input type="time" id="sc-map-time" value="${mapTime}" aria-label="Начало интервала"></label><label>До<input type="time" id="sc-map-end" value="${mapEnd}" aria-label="Конец интервала"></label></div><p id="sc-time-error" class="v3-error" role="status" ${mapTime<mapEnd?'hidden':''}>Время «до» должно быть позже времени «с».</p><div id="v3-plan-root"></div>`;drawPlan();};
function autoSelectTable(){if(!card?.data.guests||card.data.selectionKey||!config)return;const state=seatingState(),free=config.tables.filter(t=>!t.archived&&!state.busy.has(t.id)),guests=Number(card.data.guests),single=free.filter(t=>tableCapacity(t)>=guests).sort((a,b)=>(guests<5?(a.hallId?1:0)-(b.hallId?1:0):0)||tableCapacity(a)-tableCapacity(b)||a.id-b.id),chosen=single[0]||free.sort((a,b)=>tableCapacity(b)-tableCapacity(a)||a.id-b.id)[0];if(chosen){card.data.selectionKey='t:'+chosen.id;const select=$('v3-selection');if(select){select.value=card.data.selectionKey;select.dispatchEvent(new Event('change',{bubbles:true}));}}}
document.addEventListener('click',async e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.seatView){seatingView=button.dataset.seatView;const cards=$('sc-card-view'),plan=$('v3-plan-root');if(cards)cards.hidden=seatingView!=='cards';if(plan)plan.hidden=seatingView!=='plan';document.querySelectorAll('[data-seat-view]').forEach(b=>b.classList.toggle('active',b.dataset.seatView===seatingView));}if(button.dataset.seatNew){const tableId=Number(button.dataset.seatNew),date=selected,time=mapTime;try{await form();card.data.eventDate=date;card.data.startTime=time;card.data.endTime=hours(date).close||'';card.data.selectionKey='t:'+tableId;for(const [key,value] of Object.entries({eventDate:date,startTime:time,endTime:card.data.endTime,selectionKey:card.data.selectionKey})){const input=document.querySelector(`[data-v3-field="${key}"]`);if(input){input.value=value;input.dispatchEvent(new Event('change',{bubbles:true}));}}changeCard();}catch(error){notify(error);}}});
document.addEventListener('change',e=>{if(!['sc-map-time','sc-map-end'].includes(e.target.id))return;mapTime=$('sc-map-time').value;mapEnd=$('sc-map-end').value;const warning=$('sc-time-error');if(warning)warning.hidden=Boolean(mapTime&&mapEnd&&mapTime<mapEnd);setMapContext();drawPlan();renderSeatCards();if($('sc-card-groups'))$('sc-card-groups').innerHTML=groupLabels(seatingState());});

async function showZoneBookings(tableId){
 const c=clubId,date=$('v3-map-date')?.value;if(!date)return;if(!mapTime||!mapEnd||mapTime>=mapEnd){notify('Укажите корректный интервал времени');return;}
 const table=config.tables.find(t=>t.id===tableId);if(!table)return;
 const hall=config.halls.find(h=>h.id===table.hallId),ids=new Set((hall?config.tables.filter(t=>t.hallId===hall.id):[table]).map(t=>t.id));
 const d=new Date(date+'T12:00:00'),data=await api(`${v3(c)}/cards?year=${d.getFullYear()}&month=${d.getMonth()+1}`);
 if(clubId!==c||page!=='map'||$('v3-map-date')?.value!==date)return;
 const items=data.filter(b=>dayOf(b)===date&&at(b)<mapEnd&&until(b)>mapTime&&(hall&&b.selectionKey==='h:'+hall.id||b.selectionKey==='t:'+table.id||(b.seats||[]).some(s=>ids.has(s.tableId)))).sort((a,b)=>at(a).localeCompare(at(b))||a.id-b.id);
 const dialog=document.createElement('dialog');dialog.className='v3-catalog-dialog v3-zone-bookings';dialog.setAttribute('aria-label','Банкеты: '+(hall?.name||table.name));
 dialog.innerHTML=`<div class="v3-picker-head"><div><h2>${esc(hall?.name||table.name)}</h2><span class="muted">${displayDate(date)}</span></div><button type="button" class="v3-picker-close" aria-label="Закрыть">×</button></div><div class="v3-picker-list">${items.length?bookingList(items):'<div class="v3-empty">На выбранную дату банкетов нет</div>'}</div>`;
 dialog.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.classList.contains('v3-picker-close'))dialog.close();if(button.dataset.v3Open){e.stopPropagation();dialog.close();openDetail(Number(button.dataset.v3Open)).catch(notify);}});
 dialog.addEventListener('close',()=>dialog.remove(),{once:true});document.body.append(dialog);dialog.showModal();
}

async function renderStats(){const c=clubId;const data=await api(`${v3(c)}/stats?year=${month.getFullYear()}&month=${month.getMonth()+1}`);if(page!=='owner-stats'||c!==clubId)return;$('page').innerHTML=`<div class="v3-title"><h1>Статистика клуба</h1><span class="muted">${month.toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}</span></div><div class="v3-stats">${[['Стоимость заказов',data.orders],['Полученные предоплаты',data.received],['Остаток к оплате',data.remaining]].map(([label,value])=>`<div class="v3-panel"><span class="muted">${label}</span><h1>${money(value)}</h1></div>`).join('')}</div><p>Подтверждённых и завершённых банкетов: ${data.count}</p><div class="v3-notice">Стоимость заказов не равна полученным деньгам. Показатели относятся к банкетам выбранного месяца.</div>`;}
function renderClubInfo(){if(!dev())return;if(managerSection==='seating'){renderLayoutEditor();wrapManager('seating');return;}const c=config.club,weekly=JSON.parse(c.weeklyHours||'{}'),dates=JSON.parse(c.dateHours||'{}');$('page').innerHTML=`<div class="v3-title"><h1>Информация о клубе</h1><span id="v3-config-status" class="v3-save"></span></div><form id="v3-config-form" class="v3-panel"><div class="v3-fields">${[['name','Название'],['address','Адрес'],['contactPhone','Контактный телефон'],['chairStock','Всего стульев'],['opensAt','Открытие по умолчанию · ЧЧ:ММ'],['closesAt','Закрытие по умолчанию · ЧЧ:ММ']].map(([key,label])=>`<label>${label}<input name="${key}" value="${esc(c[key]??'')}" ${key==='chairStock'?'type="number" min="1" max="10000"':''}></label>`).join('')}</div><details class="v3-section"><summary>Расписание по дням недели</summary><div>${['Понедельник','Вторник','Среда','Четверг','Пятница','Суббота','Воскресенье'].map((name,i)=>{const d=weekly[i+1]||{open:c.opensAt,close:c.closesAt,closed:false};return`<div class="v3-hours-row"><span class="v3-hours-day" data-short="${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'][i]}">${name}</span><label class="v3-hours-closed"><input type="checkbox" name="closed-${i+1}" ${d.closed?'checked':''}><span>Выходной</span></label><div class="v3-hours-times"><input name="open-${i+1}" value="${d.open}" aria-label="Открытие ${name}"><span aria-hidden="true">–</span><input name="close-${i+1}" value="${d.close}" aria-label="Закрытие ${name}"></div></div>`;}).join('')}</div></details><details class="v3-section"><summary>Исключения по датам</summary><div><div id="v3-date-exceptions">${Object.entries(dates).map(([date,d])=>`<div class="v3-listrow" data-exception="${date}"><span>${historyText(date)}</span><span>${d.closed?'Выходной':d.open+'–'+d.close}</span><button type="button" class="ghost" data-exception-remove="${date}">Убрать</button></div>`).join('')}</div><div class="v3-ex-grid"><label class="v3-ex-date">Дата<input type="date" id="v3-ex-date" aria-label="Дата исключения"></label><label>Открытие<input id="v3-ex-open" value="10:00" aria-label="Открытие"></label><label>Закрытие<input id="v3-ex-close" value="21:00" aria-label="Закрытие"></label><label class="v3-hours-closed v3-ex-closed"><input type="checkbox" id="v3-ex-closed"><span>Выходной</span></label><button class="secondary" type="button" data-v3-action="exception">Добавить</button></div></div></details><button class="primary" type="submit">Сохранить настройки клуба</button></form>`;drawPlan();$('v3-config-form').onsubmit=saveConfig;;if(dev())wrapManager(managerSection==='seating'?'seating':'info');}
async function saveConfig(e){e.preventDefault();const f=e.target,c=config.club;const weekly={};for(let i=1;i<=7;i++)weekly[i]={closed:f.elements['closed-'+i].checked,open:f.elements['open-'+i].value,close:f.elements['close-'+i].value};const body={weeklyHours:weekly,dateHours:JSON.parse(c.dateHours||'{}')};for(const key of ['name','address','contactPhone','opensAt','closesAt','chairStock'])body[key]=key==='chairStock'?Number(f.elements[key].value):f.elements[key].value;try{await api(`${v3()}/config`,{method:'PUT',body:JSON.stringify(body)});await getConfig(true);clubs=clubs.map(x=>x.id===clubId?config.club:x);updateClubSelector(clubId);$('v3-config-status').textContent='Настройки сохранены';}catch(err){$('v3-config-status').textContent=err.message;$('v3-config-status').classList.add('v3-error');}}
let layoutEditor=null,layoutSaving=false;
const tableCapacity=t=>Number(t.capacity??config?.types.find(type=>type.id===t.typeId)?.capacity??4);
const layoutRatio=()=>Number(config?.club.planAspectRatio)||1122/633;
const shapeName=shape=>({RECTANGLE:'Прямоугольный',SQUARE:'Квадратный',ROUND:'Круглый'}[shape]||'Прямоугольный');
const layoutIcon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',rotate:'<path d="M20 7v5h-5m5 0a8 8 0 1 0-2 5"/>',trash:'<path d="M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13M10 11v5m4-5v5"/>',save:'<path d="M5 3h12l4 4v14H3V3h2Zm2 0v6h10V3M7 21v-8h10v8"/>',image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1"/><path d="m3 16 6-6 5 5 3-3 4 4"/>',move:'<path d="M12 3v18M3 12h18M9 6l3-3 3 3M9 18l3 3 3-3M6 9l-3 3 3 3m12-6 3 3-3 3"/>'})[name]||''}</svg>`;
function tablePayload(t){return{name:t.name,typeId:t.typeId,hallId:t.hallId||null,x:t.x,y:t.y,width:t.width,height:t.height,capacity:tableCapacity(t),rotation:Number(t.rotation)||0,archived:Boolean(t.archived),version:t.version??0};}
function layoutMessage(text,error=false){const node=$('ld-status');if(node){node.textContent=text;node.classList.toggle('v3-error',error);}const button=$('ld-save');if(button){button.disabled=layoutSaving||!layoutEditor?.dirty.size;button.innerHTML=layoutIcon('save')+(layoutSaving?'Сохраняем…':'Сохранить схему');}}
function layoutDirty(t){layoutEditor.dirty.add(t.id);layoutMessage('Есть несохранённые изменения');}
function clampLayoutTable(t){t.rotation=((Math.round((Number(t.rotation)||0)*100)/100)%360+360)%360;const angle=(Number(t.rotation)||0)*Math.PI/180,ratio=layoutRatio(),rx=(Math.abs(Math.cos(angle))*t.width+Math.abs(Math.sin(angle))*t.height/ratio)/2,ry=(Math.abs(Math.sin(angle))*t.width*ratio+Math.abs(Math.cos(angle))*t.height)/2;if(rx>50||ry>50)return false;let cx=t.x+t.width/2,cy=t.y+t.height/2;cx=Math.min(Math.min(100-rx,100-t.width/2),Math.max(Math.max(rx,t.width/2),cx));cy=Math.min(Math.min(100-ry,100-t.height/2),Math.max(Math.max(ry,t.height/2),cy));t.x=Number((cx-t.width/2).toFixed(3));t.y=Number((cy-t.height/2).toFixed(3));return true;}
async function flushLayout(){if(!layoutEditor?.dirty.size)return true;if(layoutSaving)return false;const editor=layoutEditor,changes=[...editor.dirty].map(id=>({id,table:tablePayload(editor.tables.find(t=>t.id===id))}));if(changes.some(change=>!change.table.name.trim()||change.table.capacity<1||change.table.capacity>50)){layoutMessage('Укажите название и вместимость от 1 до 50',true);return false;}layoutSaving=true;layoutMessage('Сохраняем…');$('ld-properties')?.querySelectorAll('input,select,button').forEach(el=>el.disabled=true);try{const saved=await api(`${v3(editor.club)}/layout`,{method:'PUT',body:JSON.stringify(changes)});for(const table of saved){const index=config.tables.findIndex(t=>t.id===table.id);if(index>=0)config.tables[index]=table;const draft=editor.tables.find(t=>t.id===table.id);if(draft)Object.assign(draft,table);editor.dirty.delete(table.id);}layoutMessage('Схема сохранена');return true;}catch(error){layoutMessage(error.message+' Изменения остались в редакторе.',true);return false;}finally{layoutSaving=false;$('ld-properties')?.querySelectorAll('input,select,button').forEach(el=>el.disabled=false);const button=$('ld-save');if(button){button.disabled=!editor.dirty.size;button.innerHTML=layoutIcon('save')+'Сохранить схему';}}}
function renderLayoutEditor(){
 if(!layoutEditor||layoutEditor.club!==clubId)layoutEditor={club:clubId,tables:config.tables.filter(t=>!t.archived).map(t=>({...t,capacity:tableCapacity(t),rotation:Number(t.rotation)||0})),dirty:new Set(),selected:null,zoom:Number(config.club.planZoom)||1};
 if(!layoutEditor.tables.some(t=>t.id===layoutEditor.selected))layoutEditor.selected=layoutEditor.tables[0]?.id||null;
 $('page').innerHTML=`<section class="v3-table-settings ld-editor"><div class="ld-toolbar"><div><h2>План и столы</h2><p class="muted">Перемещайте столы. Для поворота потяните за ручку.</p></div><div class="ld-tools"><label class="secondary ld-upload">${layoutIcon('image')}<span>Фон PNG</span><input id="ld-file" type="file" accept="image/png" aria-label="Загрузить план PNG"></label><button type="button" class="secondary" id="ld-add">${layoutIcon('plus')}Стол</button><button type="button" class="primary" id="ld-save">${layoutIcon('save')}Сохранить схему</button></div></div><div id="ld-status" role="status" class="ld-status"></div><div class="ld-grid"><section class="ld-canvas-panel"><div class="ld-canvas-tools"><span>${layoutIcon('move')}Редактор расстановки</span><div class="ld-view-controls"><button type="button" data-ld-zoom="-0.25" aria-label="Уменьшить план">−</button><output id="ld-zoom-label">100%</output><button type="button" data-ld-zoom="0.25" aria-label="Увеличить план">+</button><button type="button" data-ld-zoom="reset">Вписать</button><button type="button" id="ld-save-view">Сохранить вид</button></div></div><div class="ld-canvas-scroll"><div class="v3-plan ld-stage" id="ld-stage"></div></div><div class="ld-hint">PNG — только фон. Стены и препятствия размещаются на рисунке, а столы — здесь поверх него.</div></section><section class="ld-properties" id="ld-properties"></section></div></section>`;
 renderLayoutStage();renderLayoutProperties();layoutMessage(layoutEditor.dirty.size?'Есть несохранённые изменения':'Выберите стол для настройки');
 installPlanViewEditor();$('ld-save').onclick=()=>flushLayout();$('ld-add').onclick=()=>tableForm();$('ld-file').onchange=uploadLayoutBackground;
 
 bindLayoutDragging();
}
function installPlanViewEditor(){const scroll=document.querySelector('.ld-canvas-scroll'),stage=$('ld-stage');const resize=()=>{scroll.style.height=scroll.clientWidth/layoutRatio()+'px';};resize();const center=(x,y)=>{scroll.scrollLeft=x/100*stage.offsetWidth-scroll.clientWidth/2;scroll.scrollTop=y/100*stage.offsetHeight-scroll.clientHeight/2;};requestAnimationFrame(()=>center(config.club.planCenterX??50,config.club.planCenterY??50));const label=()=>{$('ld-zoom-label').textContent=Math.round(layoutEditor.zoom*100)+'%';};label();for(const button of document.querySelectorAll('[data-ld-zoom]'))button.onclick=()=>{const x=(scroll.scrollLeft+scroll.clientWidth/2)/stage.offsetWidth*100,y=(scroll.scrollTop+scroll.clientHeight/2)/stage.offsetHeight*100;layoutEditor.zoom=button.dataset.ldZoom==='reset'?1:Math.max(1,Math.min(4,layoutEditor.zoom+Number(button.dataset.ldZoom)));renderLayoutStage();resize();center(x,y);label();};$('ld-save-view').onclick=async()=>{const button=$('ld-save-view');button.disabled=true;try{const zoom=layoutEditor.zoom,half=50/zoom,clamp=v=>Math.max(half,Math.min(100-half,v));const body={zoom,centerX:clamp((scroll.scrollLeft+scroll.clientWidth/2)/stage.offsetWidth*100),centerY:clamp((scroll.scrollTop+scroll.clientHeight/2)/stage.offsetHeight*100),version:config.club.planViewVersion||0};const c=await api(`${v3()}/plan-view`,{method:'PUT',body:JSON.stringify(body)});config.club=c;button.textContent='Вид сохранён';layoutMessage('Этот вид схемы сохранён для всех пользователей клуба');}catch(e){layoutMessage(e.message,true);}finally{button.disabled=false;}};}
function renderLayoutStage(){const stage=$('ld-stage');if(!stage)return;stage.style.aspectRatio=String(layoutRatio());stage.style.width=layoutEditor.zoom*100+'%';stage.style.backgroundImage=`url('/api/clubs/${clubId}/plan-image?v=${planVersions.get(clubId)||1}')`;stage.innerHTML=layoutEditor.tables.map(t=>{const type=config.types.find(a=>a.id===t.typeId)||{};return`<div class="ld-node ${layoutEditor.selected===t.id?'is-selected':''}" data-ld-node="${t.id}" style="left:${t.x}%;top:${t.y}%;width:${t.width}%;height:${t.height}%;transform:rotate(${t.rotation}deg)"><button type="button" class="v3-table ld-table ${type.shape==='ROUND'?'round ':type.shape==='SQUARE'?'square ':''}" data-ld-select="${t.id}" aria-label="${esc(t.name)}, ${tableCapacity(t)} мест">${chairMarks(t,type,tableCapacity(t))}<span class="wood"><span style="transform:rotate(${-t.rotation}deg)">${esc(t.name)}</span></span></button><button type="button" class="ld-rotate-handle" data-ld-rotate="${t.id}" aria-label="Повернуть ${esc(t.name)}">${layoutIcon('rotate')}</button></div>`;}).join('')||'<div class="ld-empty">Загрузите фон и добавьте первый стол</div>';}
function renderLayoutProperties(){const panel=$('ld-properties'),t=layoutEditor.tables.find(t=>t.id===layoutEditor.selected);if(!panel)return;if(!t){panel.innerHTML='<h3>Стол не выбран</h3><p class="muted">Добавьте стол или выберите его на плане.</p>';return;}
 panel.innerHTML=`<div class="ld-properties-head"><h3>Настройки стола</h3><button type="button" class="ld-delete" id="ld-delete" aria-label="Удалить стол">${layoutIcon('trash')}</button></div><label class="ld-label">Выбранный стол<select id="ld-switch">${layoutEditor.tables.map(a=>`<option value="${a.id}" ${a.id===t.id?'selected':''}>${esc(a.name||'Без названия')}</option>`).join('')}</select></label><div class="ld-fields"><label class="ld-label ld-full">Название<input id="ld-name" value="${esc(t.name)}" maxlength="80" required></label><label class="ld-label">Форма<select id="ld-type">${config.types.map(a=>`<option value="${a.id}" ${a.id===t.typeId?'selected':''}>${shapeName(a.shape)} · ${a.capacity}</option>`).join('')}</select></label><label class="ld-label">Мест<input id="ld-capacity" type="number" min="1" max="50" value="${tableCapacity(t)}"></label><label class="ld-label ld-full">Поворот<div class="ld-input-action"><input id="ld-angle" type="number" min="0" max="359" value="${Math.round(t.rotation)}" aria-label="Поворот в градусах"><span>°</span><button type="button" id="ld-turn" aria-label="Повернуть на 90 градусов">${layoutIcon('rotate')}90°</button></div><input id="ld-angle-range" type="range" min="0" max="359" step="1" value="${Math.round(t.rotation)}" aria-label="Угол поворота"></label><label class="ld-label ld-full">Размер<input id="ld-size" type="range" min="5" max="45" step="0.5" value="${t.width}" aria-label="Размер стола"></label><label class="ld-label ld-full">Постоянная зона<select id="ld-hall"><option value="">Отдельный стол</option>${config.halls.filter(h=>!h.archived).map(h=>`<option value="${h.id}" ${h.id===t.hallId?'selected':''}>${esc(h.name)}</option>`).join('')}</select></label></div><button type="button" class="secondary ld-zone-add" id="ld-zone-add">${layoutIcon('plus')}Создать зону</button><p class="ld-hint">Стрелки на клавиатуре перемещают выбранный стол. Вместимость относится только к этому столу.</p>`;
 $('ld-switch').onchange=e=>{layoutEditor.selected=Number(e.target.value);renderLayoutStage();renderLayoutProperties();};
 const update=(fn,field)=>{if(layoutSaving)return;const old={...t};fn();if(!clampLayoutTable(t)){Object.assign(t,old);if(field)field.value=field.id==='ld-size'?old.width:old.rotation;layoutMessage('Стол такого размера не помещается под этим углом',true);return;}layoutDirty(t);renderLayoutStage();};
 $('ld-name').oninput=e=>{t.name=e.target.value;const option=$('ld-switch')?.selectedOptions[0];if(option)option.textContent=t.name||'Без названия';layoutDirty(t);renderLayoutStage();};$('ld-capacity').oninput=e=>{t.capacity=Number(e.target.value);layoutDirty(t);renderLayoutStage();};
 $('ld-type').onchange=e=>update(()=>{t.typeId=Number(e.target.value);},e.target);$('ld-hall').onchange=e=>{t.hallId=Number(e.target.value)||null;layoutDirty(t);};
 const rotate=value=>{update(()=>{t.rotation=(Math.round(Number(value))+360)%360;});$('ld-angle').value=t.rotation;$('ld-angle-range').value=t.rotation;};$('ld-angle').onchange=e=>rotate(e.target.value);$('ld-angle-range').oninput=e=>rotate(e.target.value);$('ld-turn').onclick=()=>rotate(t.rotation+90);
 $('ld-size').oninput=e=>update(()=>{const factor=Number(e.target.value)/t.width;t.width=Number(e.target.value);t.height=Math.max(2,Math.min(80,t.height*factor));},e.target);
 $('ld-delete').onclick=()=>deleteLayoutTable(t);$('ld-zone-add').onclick=async()=>{if(!await flushLayout())return;const name=await rafiPrompt('Название постоянной зоны','Новая зона');if(!name?.trim())return;try{const hall=await api(apiClub('/zones'),{method:'POST',body:JSON.stringify({name:name.trim(),x:10,y:10,width:20,height:20})});await getConfig(true);t.hallId=hall.id;layoutDirty(t);renderLayoutProperties();}catch(error){layoutMessage(error.message,true);}};
}
function bindLayoutDragging(){const stage=$('ld-stage');let drag=null;
 stage.onpointerdown=e=>{const trigger=e.target.closest('[data-ld-select],[data-ld-rotate]');if(!trigger||layoutSaving||e.button>0)return;const id=Number(trigger.dataset.ldSelect||trigger.dataset.ldRotate),t=layoutEditor.tables.find(t=>t.id===id);if(!t)return;e.preventDefault();layoutEditor.selected=id;stage.querySelectorAll('.ld-node').forEach(n=>n.classList.toggle('is-selected',Number(n.dataset.ldNode)===id));renderLayoutProperties();const bounds=stage.getBoundingClientRect(),cx=bounds.left+(t.x+t.width/2)/100*bounds.width,cy=bounds.top+(t.y+t.height/2)/100*bounds.height;drag={t,node:trigger.closest('.ld-node'),origin:{...t},x:e.clientX,y:e.clientY,bounds,cx,cy,rotation:Boolean(trigger.dataset.ldRotate),startAngle:Math.atan2(e.clientY-cy,e.clientX-cx)};stage.setPointerCapture(e.pointerId);};
 stage.onpointermove=e=>{if(!drag)return;const{t,origin,bounds,node}=drag;if(drag.rotation)t.rotation=(origin.rotation+(Math.atan2(e.clientY-drag.cy,e.clientX-drag.cx)-drag.startAngle)*180/Math.PI+720)%360;else{t.x=origin.x+(e.clientX-drag.x)/bounds.width*100;t.y=origin.y+(e.clientY-drag.y)/bounds.height*100;}if(!clampLayoutTable(t)){Object.assign(t,origin);return;}node.style.left=t.x+'%';node.style.top=t.y+'%';node.style.transform=`rotate(${t.rotation}deg)`;node.querySelector('.wood span').style.transform=`rotate(${-t.rotation}deg)`;if($('ld-angle'))$('ld-angle').value=Math.round(t.rotation);if($('ld-angle-range'))$('ld-angle-range').value=Math.round(t.rotation);};
 const finish=e=>{if(!drag)return;if(['x','y','rotation'].some(k=>Math.abs(drag.t[k]-drag.origin[k])>.05))layoutDirty(drag.t);drag=null;if(stage.hasPointerCapture(e.pointerId))stage.releasePointerCapture(e.pointerId);};stage.onpointerup=finish;stage.onpointercancel=finish;
 stage.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)||layoutSaving)return;const t=layoutEditor.tables.find(t=>t.id===layoutEditor.selected);if(!t)return;e.preventDefault();const step=e.shiftKey?5:1;if(e.key==='ArrowLeft')t.x-=step;if(e.key==='ArrowRight')t.x+=step;if(e.key==='ArrowUp')t.y-=step;if(e.key==='ArrowDown')t.y+=step;clampLayoutTable(t);layoutDirty(t);renderLayoutStage();stage.querySelector(`[data-ld-select="${t.id}"]`)?.focus({preventScroll:true});};
}
async function uploadLayoutBackground(e){const file=e.target.files[0];if(!file)return;if(file.type!=='image/png'||file.size>5000000){layoutMessage('Выберите PNG размером не более 5 МБ',true);e.target.value='';return;}if(!await flushLayout())return;layoutMessage('Загружаем фон…');const c=clubId,data=new FormData();data.append('file',file);try{const response=await fetch('/api'+apiClub('/plan-image'),{method:'POST',body:data,headers:{'X-XSRF-TOKEN':csrf()}});if(!response.ok){let text='Не удалось загрузить PNG';try{text=(await response.json()).message||text;}catch(ignore){}throw Error(text);}if(clubId!==c)return;planVersions.set(c,Date.now());await getConfig(true);renderLayoutStage();layoutMessage('Фон обновлён. Положение столов сохранено');}catch(error){layoutMessage(error.message,true);}finally{e.target.value='';}}
async function deleteLayoutTable(t){if(!await rafiConfirm('Удалить стол «'+t.name+'» со схемы и из бронирования? История банкетов сохранится.'))return;if(!await flushLayout())return;try{await api(`${v3()}/tables/${t.id}?version=${t.version??0}`,{method:'DELETE'});config.tables=config.tables.filter(a=>a.id!==t.id);layoutEditor.tables=layoutEditor.tables.filter(a=>a.id!==t.id);layoutEditor.selected=layoutEditor.tables[0]?.id||null;renderLayoutStage();renderLayoutProperties();layoutMessage('Стол удалён');}catch(error){layoutMessage(error.message,true);}}
async function tableForm(id){if(!layoutEditor||layoutEditor.club!==clubId){managerSection='seating';renderClubInfo();}if(id){if(!layoutEditor||layoutEditor.club!==clubId){managerSection='seating';renderClubInfo();}layoutEditor.selected=id;renderLayoutStage();renderLayoutProperties();return;}if(!await flushLayout())return;
 modal('Добавить стол',`<form id="ld-new-form"><div class="ld-fields"><label class="ld-label ld-full">Название<input name="name" required maxlength="80" placeholder="Например, Космос"></label><label class="ld-label">Форма<select name="shape"><option value="RECTANGLE">Прямоугольный</option><option value="SQUARE">Квадратный</option><option value="ROUND">Круглый</option></select></label><label class="ld-label">Мест<input name="capacity" type="number" min="1" max="50" value="14" required></label></div><div class="actions"><button type="button" class="secondary" id="ld-new-cancel">Отмена</button><button type="submit" class="primary">Добавить</button></div><div class="v3-error" id="ld-new-error"></div></form>`);$('ld-new-cancel').onclick=close;const form=$('ld-new-form');form.elements.shape.onchange=()=>form.elements.capacity.value=({RECTANGLE:14,SQUARE:4,ROUND:6})[form.elements.shape.value];form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;try{const shape=form.elements.shape.value,capacity=Number(form.elements.capacity.value);let type=config.types.find(t=>t.shape===shape);if(!type){type=await api(`${v3()}/types`,{method:'POST',body:JSON.stringify({name:shapeName(shape),shape,capacity})});config.types.push(type);}const width=shape==='RECTANGLE'?22:10,height=shape==='RECTANGLE'?7:width*layoutRatio(),body={name:form.elements.name.value.trim(),typeId:type.id,hallId:null,x:35,y:35,width,height,capacity,rotation:0,archived:false};const table=await api(`${v3()}/tables`,{method:'POST',body:JSON.stringify(body)});config.tables.push(table);layoutEditor.tables.push({...table});layoutEditor.selected=table.id;close();renderLayoutStage();renderLayoutProperties();layoutMessage('Стол добавлен');}catch(error){$('ld-new-error').textContent=error.message;}finally{button.disabled=false;}};
}
window.addEventListener('beforeunload',e=>{if(layoutEditor?.dirty.size){e.preventDefault();e.returnValue='';}});

async function action(a){if(a==='new'){await form();return;}if(a==='setup'){managerSection='seating';await navigate('club-info');return;}if(a==='new-table'){tableForm();return;}if(a==='new-zone'){const name=await rafiPrompt('Название постоянной зоны','Новая зона');if(!name)return;await api(apiClub('/zones'),{method:'POST',body:JSON.stringify({name,x:10,y:10,width:20,height:20})});await getConfig(true);renderClubInfo();return;}if(a==='upload-plan'){const file=$('v3-plan-file').files[0];if(!file)return;const data=new FormData();data.append('file',file);const res=await fetch('/api'+apiClub('/plan-image'),{method:'POST',body:data,headers:{'X-XSRF-TOKEN':csrf()}});if(!res.ok)throw Error('Не удалось загрузить изображение');planVersions.set(clubId,Date.now());await getConfig(true);renderClubInfo();return;}if(a==='exception'){const date=$('v3-ex-date').value;if(!date)return;const d={closed:$('v3-ex-closed').checked,open:$('v3-ex-open').value,close:$('v3-ex-close').value},dates=JSON.parse(config.club.dateHours||'{}');dates[date]=d;config.club.dateHours=JSON.stringify(dates);$('v3-date-exceptions').insertAdjacentHTML('beforeend',`<div class="v3-listrow"><span>${esc(historyText(date))} · ${d.closed?'Выходной':esc(d.open)+'–'+esc(d.close)}</span></div>`);return;}if(!card)return;
if(a==='save-draft'){if(!card.data.clientName.trim()||card.data.phone.replace(/\D/g,'').length<6){message('Укажите имя и телефон заказчика.',true);return;}if(await flushCard()){if(card.data.id)await openDetail(card.data.id);else message('Добавьте имя и телефон заказчика.',true);}return;}if(a==='back'){await navigate('calendar');return;}if(a==='discard'){clearTimeout(saveTimer);clearTimeout(recommendTimer);const id=card.data.id;card=null;cardEpoch++;bookingDirty=false;changed=savedRevision=0;if(id)await openDetail(id);else{page='calendar';render();}return;}if(a==='edit'){await fetchCatalog();card.view=false;renderCard();return;}if(a==='closing'){const h=hours(card.data.eventDate||selected);card.data.endTime=h.closed?'':h.close;$('page').querySelector('[data-v3-field=endTime]').value=card.data.endTime;changeCard();return;}if(a==='apply'){if(await flushCard(true))await openDetail(card.data.id);return;}if(a==='pdf'||a==='kitchen'){if(!card.data.id||!await flushCard())return;await downloadPdf(card.data.id,a==='kitchen'?'kitchen':'card');return;}
if(['confirm','cancel','restore','extend'].includes(a)){if(a==='confirm'&&card.data.items.some(l=>l.kind==='MENU')&&(!card.data.menuAgreed||card.data.noMenu)){card.data.menuAgreed=true;card.data.noMenu=false;changeCard();}if(a==='cancel'&&!await rafiConfirm('Отменить банкет? Столы будут освобождены.'))return;if(!await flushCard())return;if(!card.data.id){message('Сначала добавьте данные',true);return;}const id=card.data.id,b=await api(`${v3()}/cards/${id}/status`,{method:'PATCH',body:JSON.stringify({version:card.data.version,action:{confirm:'CONFIRMED',cancel:'CANCELLED',restore:'RESTORE',extend:'EXTEND'}[a]})});cachedPatch(b);card=null;bookingDirty=false;await openDetail(id);return;}if(a==='delete'){if(!await rafiConfirm('Удалить предварительный черновик без возможности восстановления?'))return;clearTimeout(saveTimer);if(saving)await saving;const id=card.data.id;await api(`${v3()}/cards/${id}?version=${card.data.version}`,{method:'DELETE'});for(const [key,value] of cache)cache.set(key,{...value,items:value.items.filter(x=>x.id!==id)});bookings=bookings.filter(b=>b.id!==id);card=null;cardEpoch++;bookingDirty=false;render();}}
document.addEventListener('input',e=>{const t=e.target;if(!card||card.view||!t.dataset.v3Field&&!t.dataset.v3Qty)return;if(t.dataset.v3Field){const key=t.dataset.v3Field;card.data[key]=t.type==='checkbox'?t.checked:key==='guests'?(t.value?Number(t.value):null):['prepayment','extraOrder'].includes(key)?Number(t.value):t.value;if(key==='noMenu')card.data.menuAgreed=t.checked||card.data.items.some(l=>l.kind==='MENU');if(key==='eventDate'){const h=hours(t.value);card.data.endTime=h.closed?'':h.close;const end=$('page').querySelector('[data-v3-field=endTime]');if(end)end.value=card.data.endTime;}}else{const line=card.data.items.find(l=>l._key===t.dataset.v3Qty);if(line)line.quantity=Number(t.value);}changeCard();});
document.addEventListener('change',e=>{const t=e.target;if(card&&t.dataset.v3Field&&(t.type==='date'||t.tagName==='SELECT')&&card.data[t.dataset.v3Field]!==t.value)t.dispatchEvent(new Event('input',{bubbles:true}));if(t.id?.startsWith('v3-map-')){selected=$('v3-map-date').value;setMapContext();const context={...planContext},c=clubId,serial=++planSerial;if(context.eventDate){const d=new Date(context.eventDate+'T12:00');api(`${v3(c)}/cards?year=${d.getFullYear()}&month=${d.getMonth()+1}`).then(data=>{if(page==='map'&&clubId===c&&serial===planSerial){bookings=data;drawPlan();renderSeatCards();if($('sc-card-groups'))$('sc-card-groups').innerHTML=groupLabels(seatingState());}}).catch(notify);}else drawPlan();}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.v3OrderToggle){const details=$('v3-order-details-'+b.dataset.v3OrderToggle);if(details){details.open=!details.open;b.setAttribute('aria-expanded',String(details.open));}return;}if(b.dataset.v3Picker){showPicker(b.dataset.v3Picker);return;}if(b.dataset.v3Month){moveMonth(Number(b.dataset.v3Month));return;}if(b.dataset.v3Day){selected=b.dataset.v3Day;const picked=new Date(selected+'T12:00:00');if(picked.getMonth()!==month.getMonth()||picked.getFullYear()!==month.getFullYear()){month=new Date(picked.getFullYear(),picked.getMonth(),1);await loadMonth();return;}document.querySelectorAll('[data-v3-day]').forEach(x=>{x.classList.toggle('selected',x.dataset.v3Day===selected);x.tabIndex=x.dataset.v3Day===selected?0:-1;});renderDay();return;}if(b.dataset.v3Open){await openDetail(Number(b.dataset.v3Open));return;}if(b.dataset.v3Action){await action(b.dataset.v3Action);return;}if(b.dataset.v3TableEdit){tableForm(Number(b.dataset.v3TableEdit));return;}if(b.dataset.v3Table){if(card?.view)return;if(!dev()&&!card&&page==='map'){await showZoneBookings(Number(b.dataset.v3Table));return;}if(dev()){tableForm(Number(b.dataset.v3Table));return;}if(!card){await fetchCatalog();await form();card.data.eventDate=planContext?.eventDate||selected;card.data.startTime='';card.data.endTime=hours(card.data.eventDate).close||'';for(const k of ['eventDate','startTime','endTime']){const el=$('page').querySelector(`[data-v3-field="${k}"]`);if(el)el.value=card.data[k];}}card.data.selectionKey='t:'+b.dataset.v3Table;$('v3-selection').value=card.data.selectionKey;changeCard();return;}if(b.dataset.v3Remove){card.data.items=card.data.items.filter(l=>l._key!==b.dataset.v3Remove);for(const kind of ['MENU','SERVICE'])$('v3-lines-'+kind).innerHTML=editLines(kind);changeCard();return;}if(b.dataset.v3TypeEdit){const type=config.types.find(t=>t.id===Number(b.dataset.v3TypeEdit));const value=await rafiPrompt('Максимум мест: '+type.name,String(type.capacity));if(value===null)return;await api(`${v3()}/types/${type.id}`,{method:'PUT',body:JSON.stringify({...type,capacity:Number(value)})});await getConfig(true);renderClubInfo();return;}if(b.dataset.v3Enable){await api(`${v3()}/staff/${b.dataset.v3Enable}/enabled?enabled=${b.dataset.enabled}`,{method:'PATCH'});await renderStaff();return;}if(b.dataset.exceptionRemove){const dates=JSON.parse(config.club.dateHours||'{}');delete dates[b.dataset.exceptionRemove];config.club.dateHours=JSON.stringify(dates);b.closest('[data-exception]').remove();}}catch(err){if(card)message(err.message,true);else notify(err);}});
// Route the original shell through the integrated workflow before the first request.
renderSearch=function(){
 $('page').innerHTML='<div class="v3-title"><h1>Поиск и клиенты</h1></div><section class="v3-panel"><form id="v3-search-form"><div class="v3-fields"><label class="v3-search-label">Имя или телефон<div class="v3-search-input"><input id="v3-search-query" placeholder="Имя / телефон"></div></label><label>Дата<input id="v3-search-date" type="date"></label></div><button class="primary v3-search-submit" type="submit">Найти</button></form><div id="v3-results"></div></section>';
 document.querySelector('#v3-search-form .v3-search-input').append($('v3-search-form').querySelector('.v3-search-submit'));$('v3-search-form').onsubmit=async e=>{e.preventDefault();const c=clubId,query=$('v3-search-query').value.trim(),params=new URLSearchParams();if(query)params.set(/^[+\\d ()-]+$/.test(query)?'phone':'name',query);if($('v3-search-date').value)params.set('date',$('v3-search-date').value);try{const result=await api(apiClub('/search?'+params));if(c===clubId&&page==='search')$('v3-results').innerHTML=bookingList(result);}catch(err){notify(err);}};
};
submitGlobalSearch=async function(){const query=$('globalSearch').value.trim();await navigate('search');if($('v3-search-query')){$('v3-search-query').value=query;$('v3-search-form').requestSubmit();}};
const oldGlobal=$('globalAdd');if(oldGlobal)oldGlobal.onclick=()=>action('new').catch(notify);
const oldMobile=$('mobileNewBooking');if(oldMobile)oldMobile.onclick=()=>action('new').catch(notify);
const clubSelect=$('club');clubSelect.onchange=async()=>{const requested=Number(clubSelect.value);if(card&&!await flushCard()){clubSelect.value=clubId;return;}card=null;cardEpoch++;clubId=requested;selected=localDate(new Date());page='calendar';bookingDirty=false;syncMobileClubPicker();await reload();};
function wrapManager(section){if(!dev())return;const root=$('page');if(root.querySelector('.v3-manager-shell'))return;const content=document.createElement('div');content.className='v3-manager-content';while(root.firstChild)content.append(root.firstChild);if(section==='info'||section==='seating'){const form=content.querySelector('#v3-config-form'),tables=content.querySelector('.v3-table-settings');if(form){form.hidden=section!=='info';if(section==='info')form.insertAdjacentHTML('afterend',`<section class="v3-panel v3-club-delete"><h3>Управление клубом</h3><p class="muted">Архив скрывает клуб из работы и сохраняет его данные.</p><button type="button" class="secondary" data-tools-archive="${clubId}">В архив</button><button class="secondary v3-danger-action" data-manager-delete="${clubId}">Удалить клуб</button></section>`);}if(tables)tables.hidden=section!=='seating';const title=content.querySelector('.v3-title h1');if(title)title.textContent=section==='info'?'Информация о клубе':'Схема и столы';}
const shell=document.createElement('div');shell.className='v3-manager-shell';shell.innerHTML=`<button class="secondary" data-manager-list>‹ Все клубы</button><div class="v3-title v3-manager-title"><div><span class="muted">Менеджер клубов</span><h1>${esc(clubs.find(c=>c.id===clubId)?.name||'Клуб')}</h1></div></div><nav class="v3-manager-tabs" aria-label="Настройки клуба">${[['info','Информация'],['seating','Схема и столы'],['staff','Сотрудники и управляющий'],['home','Главный экран']].map(([id,label])=>`<button type="button" class="${section===id?'active':''}" data-manager-tab="${id}">${label}</button>`).join('')}</nav>`;shell.append(content);root.append(shell);}
renderClubs=async function(){if(!dev())return;const active=clubs.filter(c=>!c.archived),archived=clubs.filter(c=>c.archived);$('page').innerHTML=`<div class="v3-title"><div><h1>Менеджер клубов</h1><div class="muted">Клубы, сотрудники и настройки в одном месте</div></div></div><section class="v3-panel v3-create-club-panel"><div><h2>Новый клуб</h2></div><form id="v3-create-club" class="v3-create-club"><label>Название клуба<input name="name" placeholder="Например, Облака · Северный" required maxlength="120"></label><button class="primary" type="submit">Создать</button></form><div id="v3-create-club-error" role="alert" class="v3-error"></div></section><div class="v3-club-grid">${active.map(c=>`<button class="v3-club-card" data-manager-club="${c.id}"><span class="v3-club-card-top"><strong>${esc(c.name)}</strong><span aria-hidden="true">›</span></span><span class="muted">${esc(c.address||'Адрес пока не указан')}</span><span class="v3-subtle">Информация · Схема · Аккаунты · Главный экран</span></button>`).join('')||'<p class="muted">Создайте первый клуб, чтобы настроить его.</p>'}</div><details class="v3-section"><summary>Архив клубов · ${archived.length}</summary>${archived.map(c=>`<div class="v3-listrow"><strong>${esc(c.name)}</strong><div class="v3-staff-actions"><button class="secondary" data-restoreclub="${c.id}">Восстановить</button><button class="secondary v3-danger-action" data-manager-delete="${c.id}">Удалить</button></div></div>`).join('')||'<p class="muted">Архив пуст</p>'}</details>`;$('v3-create-club').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const c=await api('/clubs',{method:'POST',body:JSON.stringify({name:e.target.elements.name.value.trim()})});clubs=await api('/clubs');clubId=c.id;updateClubSelector(c.id);syncMobileClubPicker();config=null;configClub=null;managerSection='info';await getConfig(true);await navigate('club-info');}catch(err){$('v3-create-club-error').textContent=err.message;}finally{button.disabled=false;}};};
renderDashboard=async function(){if(!dev())return;const c=clubs.find(x=>x.id===clubId)||config?.club||{},opts=[['showStats','Статистика клуба за месяц'],['showReminders','Блок «Ждут подтверждения»'],['showRevenue','Суммы в списке банкетов'],['showZones','Рассадка в списке банкетов']];$('page').innerHTML=`<div class="v3-title"><h1>Главный экран</h1></div><form id="v3-home-settings" class="v3-panel"><p class="muted">Календарь и список банкетов выбранного дня остаются основой экрана.</p>${opts.map(([id,label])=>`<label class="setting-toggle"><span>${label}</span><input type="checkbox" role="switch" aria-label="${label}" aria-checked="${c[id]!==false}" name="${id}" ${c[id]!==false?'checked':''}></label>`).join('')}<button type="submit" class="primary">Сохранить настройки</button><span id="v3-home-status" role="status"></span></form>`;$('v3-home-settings').onsubmit=async e=>{e.preventDefault();try{const values=Object.fromEntries(opts.map(([id])=>[id,e.target.elements[id].checked])),updated=await api('/clubs/'+clubId+'/dashboard',{method:'PUT',body:JSON.stringify(values)});clubs=clubs.map(x=>x.id===clubId?updated:x);if(config)config.club={...config.club,...updated};$('v3-home-status').textContent='Настройки сохранены';}catch(err){$('v3-home-status').textContent=err.message;}};wrapManager('home');};
document.addEventListener('click',async e=>{const button=e.target.closest('button');if(!button||(!dev()&&!owner()))return;try{if(button.dataset.staffDelete){if(!await rafiConfirm('Удалить аккаунт «'+button.dataset.staffName+'»? Доступ во все его филиалы будет прекращён. История банкетов сохранится.'))return;await api(`${v3()}/staff/${button.dataset.staffDelete}`,{method:'DELETE'});await renderStaff();notify('Аккаунт удалён');return;}if(!dev())return;if(button.dataset.toolsArchive){if(!await rafiConfirm('Переместить клуб в архив? Брони и настройки сохранятся.'))return;await api('/clubs/'+button.dataset.toolsArchive+'/archive',{method:'PATCH'});clubs=await api('/clubs');config=null;configClub=null;clubId=clubs.find(x=>!x.archived)?.id||null;updateClubSelector(clubId);syncMobileClubPicker();page='clubs';renderClubs();notify('Клуб в архиве');return;}if(button.dataset.managerDelete){const c=clubs.find(x=>x.id===Number(button.dataset.managerDelete));if(!c)return;if(!await rafiConfirm('Удалить клуб «'+c.name+'» навсегда? Будут удалены все его банкеты, схема, меню и услуги. Доступ сотрудников к другим филиалам сохранится. Это действие нельзя отменить.'))return;await api('/clubs/'+c.id+'?permanent=true',{method:'DELETE'});clubs=await api('/clubs');clubId=clubs.find(x=>!x.archived)?.id||null;config=null;configClub=null;cache.clear();updateClubSelector(clubId);syncMobileClubPicker();page='clubs';renderClubs();notify('Клуб удалён');return;}if(button.hasAttribute('data-manager-list')){await navigate('clubs');return;}if(button.dataset.managerClub){const c=Number(button.dataset.managerClub);clubId=c;updateClubSelector(c);syncMobileClubPicker();config=null;configClub=null;managerSection='info';await getConfig(true);await navigate('club-info');return;}if(button.dataset.managerTab){managerSection=button.dataset.managerTab;await navigate(managerSection==='staff'?'staff':managerSection==='home'?'dashboard':'club-info');return;}}catch(err){notify(err);}});
let statsYear=new Date().getFullYear(),statsMonth=new Date().getMonth()+1,statsPeriod='month',statsSerial=0;
function statsTiles(data){return `<div class="tools-stats">${[['Банкетов',data.count,false],['Стоимость заказов',data.orders,true],['Получено предоплат',data.received,true],['Остаток к оплате',data.remaining,true],['Гостей',data.guests,false],['Средний заказ',data.average,true]].map(([label,value,currency])=>`<article class="v3-panel"><span class="muted">${label}</span><strong>${currency?money(value||0):value||0}</strong></article>`).join('')}</div><div class="v3-subtle">Предварительных: ${data.preliminary||0} · Отменённых: ${data.cancelled||0}</div>`;}
async function renderStats(){const c=clubId,serial=++statsSerial;const query=`year=${statsYear}${statsPeriod==='month'?'&month='+statsMonth:''}`;const data=await api(`${v3(c)}/statistics?${query}`);if(page!=='owner-stats'||c!==clubId||serial!==statsSerial)return;$('page').innerHTML=`<div class="v3-title"><h1>Статистика клуба</h1></div><section class="v3-panel tools-period"><label>Период<select id="stats-period"><option value="month" ${statsPeriod==='month'?'selected':''}>Месяц</option><option value="year" ${statsPeriod==='year'?'selected':''}>Год</option></select></label><label>Год<input type="number" id="stats-year" min="2000" max="2200" value="${statsYear}"></label>${statsPeriod==='month'?`<label>Месяц<select id="stats-month">${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${statsMonth===i+1?'selected':''}>${new Date(2026,i,1).toLocaleDateString('ru-RU',{month:'long'})}</option>`).join('')}</select></label>`:''}<button class="primary" id="stats-export">Скачать Excel</button></section>${statsTiles(data)}<p class="v3-notice">Суммы относятся к подтверждённым и завершённым банкетам выбранного периода. Стоимость заказов не равна полученным деньгам: приложение учитывает предоплаты, а не окончательные расчёты.</p>`;for(const id of ['stats-period','stats-month','stats-year']){const input=$(id);if(input)input.onchange=()=>{const y=Number($('stats-year').value);if(y<2000||y>2200){notify('Выберите год от 2000 до 2200');return;}statsYear=y;statsMonth=Number($('stats-month')?.value||statsMonth);statsPeriod=$('stats-period').value;renderStats().catch(notify);};}$('stats-export').onclick=async()=>{const button=$('stats-export');button.disabled=true;try{const response=await fetch(`/api${v3(c)}/statistics.xlsx?${query}`,{credentials:'same-origin'});if(!response.ok)throw Error('Не удалось выгрузить отчёт');const url=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=url;link.download=`Rafi-${statsYear}${statsPeriod==='month'?'-'+pad(statsMonth):''}.xlsx`;link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);notify('Отчёт подготовлен');}catch(e){notify(e);}finally{button.disabled=false;}};}
async function renderStaff(){const c=clubId,list=await api(`${v3(c)}/staff`);if(c!==clubId||page!=='staff')return;const available=clubs.filter(c=>!c.archived&&(dev()||(profile.clubIds||[profile.clubId]).includes(c.id)));$('page').innerHTML=`<div class="v3-title"><h1>${dev()?'Сотрудники и управляющий':'Сотрудники'}</h1></div><div class="tools-staff-layout"><section class="v3-panel"><h2>Аккаунты клуба <span class="muted">${list.length}</span></h2><div class="tools-staff-list">${list.map(u=>`<article class="tools-person"><span class="tools-avatar">${esc((u.displayName||u.username||'А')[0].toUpperCase())}</span><div class="tools-person-info"><strong>${esc(u.displayName||u.username)}</strong><span>${esc(u.username)} · ${u.role==='OWNER'?'Управляющий':'Администратор'}</span><small>${u.enabled?'Активен':'Доступ отключён'} · ${(u.clubIds||[]).length} филиал(а)</small></div>${u.username!==profile.username&&(dev()||u.role==='ADMIN'&&(u.clubIds||[]).every(id=>(profile.clubIds||[profile.clubId]).includes(id)))?`<div class="tools-person-actions"><button class="secondary" data-v3-enable="${u.id}" data-enabled="${!u.enabled}">${u.enabled?'Отключить':'Включить'}</button><button class="secondary v3-danger-action" data-staff-delete="${u.id}" data-staff-name="${esc(u.displayName||u.username)}">Удалить</button></div>`:''}</article>`).join('')||'<p class="muted">Сотрудников пока нет</p>'}</div></section><section class="v3-panel"><h2>Новый сотрудник</h2><form id="v3-staff-form"><div class="v3-fields"><label>Имя<input name="displayName" maxlength="120" autocomplete="off"></label><label>Логин<input name="username" required pattern="[a-zA-Z0-9_.-]{3,40}" maxlength="40" autocomplete="off"></label><label>Пароль<input name="password" type="password" required minlength="8" autocomplete="new-password"></label><label>Роль<select name="role"><option value="ADMIN">Администратор</option>${dev()?'<option value="OWNER">Управляющий</option>':''}</select></label></div><fieldset class="tools-branches"><legend>Доступ к филиалам</legend>${available.map(c=>`<label class="v3-check"><input type="checkbox" name="clubIds" value="${c.id}" ${c.id===clubId?'checked':''}>${esc(c.name)}</label>`).join('')}</fieldset><button class="primary" type="submit">Создать аккаунт</button><div id="v3-staff-error" role="status" class="v3-error"></div></form></section></div>`;$('v3-staff-form').onsubmit=async e=>{e.preventDefault();const f=e.target,ids=[...f.querySelectorAll('[name=clubIds]:checked')].map(x=>Number(x.value));try{if(!ids.includes(c))throw Error('Оставьте доступ к текущему клубу');await api(`${v3(c)}/staff`,{method:'POST',body:JSON.stringify({username:f.elements.username.value.trim(),password:f.elements.password.value,displayName:f.elements.displayName.value.trim(),role:f.elements.role.value,clubIds:ids})});await renderStaff();notify('Аккаунт создан');}catch(err){$('v3-staff-error').textContent=err.message;}};if(dev())wrapManager('staff');}
async function fetchFormData(url,body){const response=await fetch(url,{method:'POST',body,headers:{'X-XSRF-TOKEN':csrf()}});if(!response.ok){let message='Не удалось загрузить фото';try{message=(await response.json()).message||message;}catch(ignore){}throw Error(message);}return response.json();}
async function copyText(text){try{await navigator.clipboard.writeText(text);notify('Скопировано');}catch(e){modal('Скопируйте текст',`<textarea readonly class="tools-copy">${esc(text)}</textarea>`);$('modalcontent').querySelector('textarea').select();}}
async function renderPresentation(){const c=clubId,data=await api(`${v3(c)}/presentation`);if(c!==clubId||page!=='presentation')return;let settings=data.settings;const url=()=>location.origin+'/p/'+settings.token;$('page').innerHTML=`<div class="v3-title"><h1>Презентация клуба</h1></div><div class="tools-presentation-layout"><section class="v3-panel"><h2>Публичная страница</h2><p class="muted">Фотографии, описание, меню и услуги — без входа в Rafi.</p><form id="presentation-form"><label>О клубе<textarea name="description" maxlength="4000" rows="4">${esc(settings.description||'')}</textarea></label>${[['published','Опубликовать страницу'],['showMenu','Показывать меню'],['showServices','Показывать услуги']].map(([key,label])=>`<label class="setting-toggle"><span>${label}</span><input type="checkbox" role="switch" name="${key}" ${settings[key]?'checked':''}></label>`).join('')}<button class="primary" type="submit">Сохранить</button><span id="presentation-status" role="status"></span></form><div class="tools-share"><button type="button" class="secondary" id="presentation-copy">Копировать ссылку</button><button type="button" class="secondary" id="presentation-share">Поделиться</button><a class="secondary" id="presentation-open" target="_blank" rel="noopener" href="${settings.token?url():'#'}">Открыть страницу</a></div><p class="v3-subtle">${location.hostname==='localhost'||location.hostname==='127.0.0.1'?'Сейчас Rafi открыт локально. Для клиентов понадобится доступный из интернета адрес.':'Ссылка откроется у любого, пока публикация включена.'}</p></section><section class="v3-panel"><h2>Фотографии</h2><form id="presentation-photo-form"><div class="v3-fields"><label>Категория<select name="category">${['Клуб','Зоны и столы','Игровые площадки','Праздники'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Подпись<input name="caption" maxlength="120" placeholder="Например, зона Космос"></label></div><label class="tools-upload">Выбрать фото<input type="file" name="file" accept="image/png,image/jpeg" required></label><button class="primary" type="submit">Добавить фото</button><span id="presentation-photo-status" role="status"></span></form><p class="v3-subtle">До 30 фото, PNG или JPEG до 8 МБ. Добавляйте фотографии, разрешённые для публичного показа.</p><div class="tools-gallery">${data.photos.map(p=>`<figure><img loading="lazy" src="/api${v3(c)}/presentation/photos/${p.id}" alt="${esc(p.caption||p.category)}"><figcaption><strong>${esc(p.caption||p.category)}</strong><small>${esc(p.category)}</small><button class="secondary" data-photo-delete="${p.id}">Удалить</button></figcaption></figure>`).join('')||'<p class="muted">Фотографий пока нет</p>'}</div></section></div>`;
const updateShare=()=>{for(const id of ['presentation-copy','presentation-share'])$(id).disabled=!settings.published||!settings.token;$('presentation-open').hidden=!settings.published||!settings.token;};updateShare();$('presentation-form').onsubmit=async e=>{e.preventDefault();const f=e.target;try{settings=await api(`${v3(c)}/presentation`,{method:'PUT',body:JSON.stringify({version:settings.version,description:f.elements.description.value,published:f.elements.published.checked,showMenu:f.elements.showMenu.checked,showServices:f.elements.showServices.checked})});$('presentation-status').textContent=settings.published?'Опубликовано':'Публикация выключена';$('presentation-open').href=url();updateShare();}catch(e){$('presentation-status').textContent=e.message;}};$('presentation-copy').onclick=()=>copyText(url());$('presentation-share').onclick=async()=>{if(navigator.share)try{await navigator.share({title:config.club.name,url:url()});}catch(e){if(e.name!=='AbortError')copyText(url());}else copyText(url());};$('presentation-photo-form').onsubmit=async e=>{e.preventDefault();try{await fetchFormData(`/api${v3(c)}/presentation/photos`,new FormData(e.target));await renderPresentation();notify('Фото добавлено');}catch(e){$('presentation-photo-status').textContent=e.message;}};for(const button of document.querySelectorAll('[data-photo-delete]'))button.onclick=async()=>{if(!await rafiConfirm('Удалить фотографию из презентации?'))return;try{await api(`${v3(c)}/presentation/photos/${button.dataset.photoDelete}`,{method:'DELETE'});await renderPresentation();}catch(e){notify(e);}};}
async function renderBroadcast(){const c=clubId,people=await api(`${v3(c)}/recipients`);if(c!==clubId||page!=='broadcast')return;$('page').innerHTML=`<div class="v3-title"><h1>Рассылка</h1></div><div class="tools-broadcast"><section class="v3-panel"><h2>Сообщение</h2><label>Текст SMS<textarea id="broadcast-text" maxlength="2000" rows="6" placeholder="Текст сообщения"></textarea></label><div class="v3-subtle" id="broadcast-count">0 символов</div><p class="v3-notice">Провайдер не подключён. Rafi подготовит текст и получателей; отправка выполняется в приложении сообщений телефона. Доступность группового SMS зависит от устройства.</p><div class="tools-share"><button class="primary" id="broadcast-open">Открыть SMS</button><button class="secondary" id="broadcast-copy">Копировать текст</button><button class="secondary" id="broadcast-phones">Копировать номера</button></div><div id="broadcast-status" role="status"></div></section><section class="v3-panel"><h2>Получатели <small id="broadcast-selected">0</small></h2><input id="broadcast-search" aria-label="Найти получателя" placeholder="Имя или телефон"><label class="v3-check"><input type="checkbox" id="broadcast-all">Выбрать всех найденных</label><div class="tools-recipients">${people.map(p=>`<label class="tools-recipient" data-name="${esc((p.name+' '+p.phone).toLowerCase())}"><input type="checkbox" data-recipient value="${esc(p.phone)}"><span><strong>${esc(p.name)}</strong><small>${esc(p.phone)}</small></span></label>`).join('')||'<p class="muted">Клиентов с телефоном пока нет</p>'}</div><p class="v3-subtle">Отмечайте получателей, согласившихся получать сообщения.</p></section></div>`;const selected=()=>[...document.querySelectorAll('[data-recipient]:checked')].map(el=>el.value);const update=()=>{$('broadcast-selected').textContent=selected().length;$('broadcast-count').textContent=$('broadcast-text').value.length+' символов';};$('broadcast-text').oninput=update;for(const input of document.querySelectorAll('[data-recipient]'))input.onchange=update;$('broadcast-search').oninput=e=>{for(const row of document.querySelectorAll('.tools-recipient'))row.hidden=!row.dataset.name.includes(e.target.value.toLowerCase());$('broadcast-all').checked=false;};$('broadcast-all').onchange=e=>{for(const row of document.querySelectorAll('.tools-recipient:not([hidden])'))row.querySelector('input').checked=e.target.checked;update();};$('broadcast-copy').onclick=()=>copyText($('broadcast-text').value);$('broadcast-phones').onclick=()=>copyText(selected().join(', '));$('broadcast-open').onclick=()=>{const numbers=selected(),text=$('broadcast-text').value.trim();if(!numbers.length||!text){$('broadcast-status').textContent='Введите сообщение и выберите получателей';return;}if(numbers.join(',').length>1500){$('broadcast-status').textContent='Слишком много номеров для одной ссылки. Выберите меньшую группу или скопируйте номера.';return;}const link=document.createElement('a');link.href='sms:'+numbers.join(',')+(/iPad|iPhone|iPod/.test(navigator.userAgent)?'&':'?')+'body='+encodeURIComponent(text);link.click();$('broadcast-status').textContent='Сообщение подготовлено. Отправку подтвердите в приложении SMS.';};}

function renderHomeStats(){const root=$('tools-home-stats');if(!root)return;root.hidden=config?.club.showStats===false;if(root.hidden)return;const key=currentKey().split(':')[1],active=bookings.filter(b=>dayOf(b).slice(0,7)===key&&['CONFIRMED','FINISHED'].includes(b.status)),total=active.reduce((n,b)=>n+Number(b.total||0),0);root.innerHTML=`<section class="tools-home-stats" aria-label="Итоги месяца"><div class="tools-home-period"><span>Итоги месяца</span><strong>${month.toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}</strong></div><div class="tools-home-metrics"><div><span>Подтверждены и прошли</span><strong>${active.length}<small> банкетов</small></strong></div>${config?.club.showRevenue!==false?`<div><span>Стоимость заказов</span><strong>${money(total)}</strong></div>`:''}</div></section>`;}
function refreshBarIcons(){
 const paths={calendar:'<rect x="4" y="5" width="16" height="16" rx="3"/><path d="M8 3v4m8-4v4M4 10h16m-11 4h.01M12 14h.01M15 14h.01M9 17h.01M12 17h.01"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3V6Zm6-3v15m6-12v15"/>',menu:'<path d="M5 3v6a3 3 0 0 0 6 0V3M8 3v18M19 21V3c-3 2-4 5-4 9h4"/>',services:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',clubs:'<rect x="4" y="4" width="16" height="17" rx="2"/><path d="M8 8h1m6 0h1M8 12h1m6 0h1m-6 9v-5h4v5"/>','owner-stats':'<path d="M4 4v16h16M8 16v-4m5 4V8m5 8v-7"/>',staff:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-2a6 6 0 0 1 12 0v2m1-16a3 3 0 0 1 0 6m3 10v-2a6 6 0 0 0-3-5"/>',more:'<path d="M5 6h14M5 12h14M5 18h14"/>'};
 const svg=id=>`<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[id]||paths.more}</svg>`;
 document.querySelectorAll('.sidebar .nav [data-page]').forEach(button=>{let mark=button.querySelector('.navdot');if(!mark){mark=document.createElement('span');button.prepend(mark);}mark.className='navdot rafi-nav-icon';mark.setAttribute('aria-hidden','true');mark.innerHTML=svg(button.dataset.page);});
 document.querySelectorAll('.mobile-bottom-nav button').forEach(button=>{const mark=button.querySelector('.mobile-icon');if(mark)mark.innerHTML=svg(button.dataset.mobilePage||'more');});
}

async function boot(){await window.rafiStart();if(!profile)return;const avatar=document.querySelector('.account-avatar');if(avatar){avatar.textContent=(profile.displayName||profile.username||'А').trim().slice(0,1).toLocaleUpperCase('ru-RU');}$('mobileAccountRole').textContent=dev()?'Разработчик':owner()?'Управляющий':'Администратор';const nav=document.querySelector('.sidebar .nav');const extra=[...(owner()?[['owner-stats','Статистика'],['staff','Сотрудники']]:[]),['presentation','Презентация клуба'],['broadcast','Рассылка']];for(const [id,label] of extra){const b=document.createElement('button');b.dataset.page=id;b.innerHTML='<span class="navdot"></span>'+esc(label);b.onclick=()=>navigate(id);nav.append(b);}document.body.classList.toggle('owner',owner());if(owner()){for(const id of ['calendar','owner-stats','staff','map','search','menu','services','presentation','broadcast']){const item=nav.querySelector('[data-page="'+id+'"]');if(item)nav.append(item);}}const dashboard=document.querySelector('[data-page=dashboard]');if(dashboard)dashboard.remove();if(dev()){document.querySelector('.sidebar [data-page=clubs]')?.removeAttribute('hidden');document.querySelector('.sidebar [data-page=map]')?.remove();document.querySelector('.dev-tab[data-mobile-page=map]')?.remove();const item=document.querySelector('.dev-tab[data-mobile-page=clubs]');if(item)item.innerHTML='<span class="mobile-icon">▤</span>Менеджер';}refreshBarIcons();const theme=$('mobileThemeSwitch'),header=document.querySelector('.workspace>.top');if(theme&&header)header.prepend(theme);document.querySelectorAll('.developer-only').forEach(el=>{if(!dev())el.style.display='none';});}
window.addEventListener('beforeunload',e=>{if(card&&changed!==savedRevision||[...suspendedDrafts.values()].some(d=>d.changed!==d.savedRevision)){e.preventDefault();e.returnValue='';}});
setInterval(()=>{if(!document.hidden&&!card&&clubId&&page==='calendar')loadMonth(true).catch(()=>{});},30000);
// No generic custom time widget: explicit HH:MM fields keep mobile editing predictable.
boot().catch(notify);
})();

document.addEventListener('toggle',e=>{if(e.target.matches?.('.tools-order-edit .v3-order-details')){const button=e.target.closest('.v3-order-section')?.querySelector('.v3-order-toggle');if(button)button.setAttribute('aria-expanded',String(e.target.open));}},true);
